import test;

struct Builder {
    val: int
}

// Mutates self and returns self by reference -- see
// tests/06_structs/23_self_pointer_chaining.tr for why this (rather than a
// by-value `Builder` return) is the idiomatic way to support chaining, and
// for why the return type is `&Builder` (issue #238: a plain function may
// never return a raw ptr/T* type, even inside `unsafe { }` -- it used to
// be `Builder*` here too) with an explicit `unsafe { self to &Builder }`
// to satisfy it (self's own synthesized type is still a raw pointer,
// unchanged by this issue, but always non-null by construction).
//
// This method was MISSING entirely until this fix: the original test called
// `b.push(1).push(2)` against a `Builder` struct that declared zero methods.
// Before TypeChecker::visitMethodCall() gained a real "does this method
// exist on this struct" check (see StructMethodNotFoundError in Errors.h),
// an unresolved struct-method call was silently permissive all the way
// through Codegen -- both calls just vanished from the compiled program
// with no error, so this test "passed" without the Pratt parser's chaining
// behavior ever actually being exercised semantically (only parsed, never
// resolved or executed). Now that the compiler correctly rejects a call to
// a genuinely nonexistent method, the test needs a REAL method to chain
// against for its own claimed purpose to mean anything.
fn Builder.push(int x): &Builder {
    self.val = self.val + x;
    unsafe {
        return self to &Builder;
    }
}

fn main(): int {
    mut b: Builder = Builder::default();

    // Test Pratt Parser's ability to chain method calls
    b.push(1).push(2);
    test::assert(b.val == 3, "chained push(1).push(2) should leave val == 3");

    return 0;
}

// Regression test: string literals support the full standard C-style
// escape set, not just \n/\t/\\/\" -- \r (carriage return) specifically
// used to silently become a literal 'r' character instead of an actual
// CR byte, corrupting anything relying on real \r\n line endings (found
// writing examples/http_server.tr's HTTP response headers). Also covers
// \a \b \f \v \0 \', all newly recognized alongside \r.

import io;
import strings;

import test;
fn main(): int {
    immut withCR: string = "a\rb";
    test::assert(strings::length(withCR) == 3, "\\r must be exactly one byte, not swallowed or literal 'r'+extra");
    // '\r' as a standalone escaped byte cannot equal the two-character
    // sequence 'r' would have produced before this fix.
    test::assert(withCR != "arb", "\\r must not silently become a literal 'r'");

    immut withTab: string = "x\ty";
    test::assert(strings::length(withTab) == 3, "\\t still works alongside the new escapes");

    immut withQuote: string = "it\'s fine";
    test::assert(strings::contains(withQuote, "it"), "\\' is a recognized escape");

    immut withBackslash: string = "a\\b";
    test::assert(strings::length(withBackslash) == 3, "\\\\ still produces a single literal backslash");

    println("all escape sequences resolved correctly");
    return 0;
}

// `to` binds tighter than comparison and the logical operators, and looser
// than the arithmetic and bitwise ones: a cast is an operand of `<`, `==`,
// `&&` and `||`, and `+`/`|` are operands of a cast.

import test;

fn main(): int {
    immut a: int = 1;
    immut s: double = 9.7;
    immut mask: int = 6;

    // `(a < 3) && ((s to int) > 5)`
    test::assert(a < 3 && s to int > 5, "a cast is an operand of `>` and `&&`");
    test::assert(s to int == 9, "a cast is an operand of `==`");
    test::assert(a > 3 || s to int != 10, "a cast is an operand of `!=` and `||`");
    test::assert(9 <= s to int, "a cast on the right of a comparison");

    // `(1 + 2) to double` and `(mask | 1) to double`
    test::assert(1 + 2 to double == 3.0, "`+` is an operand of a cast");
    test::assert(mask | 1 to double == 7.0, "`|` is an operand of a cast");

    // A comparison's result is cast by parenthesising the comparison.
    test::assert((a < 3).toString() == "true", "a parenthesised comparison");
    return 0;
}

