// Regression test (was DISCOVERED_ISSUES.md #14): `mut arr: int[5];` (no
// explicit bracketed initializer) used to fail to parse with "Expected '='
// after variable type" -- the language required a full literal like
// `int[5] = [0, 0, 0, 0, 0]` even when zero-initialization was all that was
// needed. Re-verified fixed: an array declared without an initializer is
// zero-initialized and safely assignable element-by-element afterward.
//
// SEM-004 (§12.6, FREEZE.md §6.4) update: storage is still always zeroed
// (F-INIT-2), but the STATIC definite-assignment check now applies to
// arrays too, at whole-array granularity -- elements are not tracked
// individually. An element WRITE (`arr[0] = 10`) counts as assigning the
// entire array, which is what makes every read below (including of an
// untouched element, still genuinely 0 from the zero-fill) legal. A read
// with NO prior element write or initializer at all is now E008 --
// see fail_array_use_before_any_write.tr.

import test;

fun main(): int {
    mut arr: int[5];
    arr[0] = 10;
    arr[1] = 20;
    arr[4] = 50;

    // Untouched elements must be zero-initialized, not garbage.
    test::assert(arr[2] == 0, "");
    test::assert(arr[3] == 0, "");

    test::assert(arr[0] == 10, "");
    test::assert(arr[1] == 20, "");
    test::assert(arr[4] == 50, "");

    // Same for a double array -- the first element WRITE (not the read)
    // is what assigns `darr` as a whole; reading the untouched arr[0]
    // afterward is legal and still genuinely 0.0 from the zero-fill.
    mut darr: double[3];
    darr[1] = 3.5;
    test::assert(darr[0] == 0.0, "");
    test::assert(darr[1] == 3.5, "");

    return 0;
}

// Regression test (was DISCOVERED_ISSUES.md #15 and #23):
//   #15 — SymbolTable::canAssign checked `From->getName() == "void*"` when
//        allowing an untyped FFI pointer to coerce into a typed pointer
//        (e.g. int*), but the untyped pointer type is actually named "ptr",
//        not "void*" -- so `mut p: int* = malloc(8);` was rejected outright
//        (required declaring `extern fn malloc(...): int*;` as a workaround
//        to bypass the broken check).
//   #23 — explicit `ptr to StructName` casts were rejected
//        ("Cannot explicitly cast 'ptr' to 'Node'"), which blocked dynamic
//        allocation of structs / building heap-based recursive structures.
// Both re-verified fixed.

import test;

extern fn malloc(size: int): ptr;
extern fn free(p: ptr): void;

struct Node {
    val: int
}

// (issue #238) Every raw pointer local below needs `unsafe { }` around its
// declaration/cast (FINAL_SPRINT.md's Track A "Caller-side locals" rule),
// and `h.val` -- a field access THROUGH the raw `Node*` base `h` -- is a
// gated "dereference" (no explicit deref operator exists).
fn main(): int {
    unsafe {
        // #15: untyped `ptr` from malloc coerces directly into a typed pointer.
        mut ip: int* = malloc(8);
        test::assert(ip != null, "");

        // #23: explicit ptr -> struct-pointer cast, for heap-allocated structs.
        let mut raw: ptr = malloc(8);
        mut h: Node* = raw to Node*;
        h.val = 77;
        test::assert(h.val == 77, "");

        free(raw);
        free(ip);
    }
    return 0;
}

