// Regression guard for AliasAnalysisPass's identity-vs-name tracking fix
// (see src/analysis/AliasAnalysis.cpp's doc comment): freeing a variable that merely
// SHARES A NAME with an already-freed variable in an outer scope -- but is
// actually a distinct, never-allocated shadowing declaration -- must NOT be
// flagged as a double free. Before the fix, name-based (rather than
// resolved-identity-based) tracking left a stale freed-allocation entry
// under "p" that the inner shadowing `mut p: int* = null;` never cleared
// (its initializer is neither a malloc()/realloc() call nor a plain
// variable alias, so neither tracked branch ran), so the inner free(p) was
// misread as re-freeing the outer allocation.

import io;

@ownership(acquires)
extern fn malloc(size: int): int*;

@ownership(releases: p)
extern fn free(p: int*): void;

// (issue #238) Every raw `int*` local below needs `unsafe { }` around its
// declaration (FINAL_SPRINT.md's Track A "Caller-side locals" rule).
fn main(): int {
    unsafe {
        mut p: int* = malloc(sizeof(int) * 4);
        free(p);

        if true {
            mut p: int* = null;
            free(p);
            puts("freed the shadowed (null) p, not the outer one");
        }
    }

    return 0;
}

// Regression test: lib/std/mem.tr's newer additions -- alloc_aligned,
// usable_size, and Pool/free_pool (bulk-free allocation tracking) --
// exercised end to end. See 14_mem_stdlib.tr for the original module's
// core allocator wrappers.

import mem;
import io;

import test;
fn main(): int {
    // alloc_aligned: the returned address must actually be a multiple of
    // the requested alignment. Turf has no bitwise AND on... actually it
    // does (see tests/11_bitwise_ops/) -- but there's still no ptr->int
    // cast to check the address numerically, so this just confirms the
    // call succeeds and the memory is usable for the requested size.
    // (issue #238) `aligned`'s raw `void*` declaration needs `unsafe { }`
    // (FINAL_SPRINT.md's Track A "Caller-side locals" rule) -- the
    // mem::*() calls themselves stay ordinary, ungated calls (`lib/std` is
    // exempt from the gate).
    unsafe {
        mut aligned: void* = mem::alloc_aligned(64, 128);
        test::assert(aligned != null, "alloc_aligned should succeed for a valid alignment/size");
        test::assert(mem::usable_size(aligned) >= 128, "usable_size must be at least what was requested");
        mem::free(aligned);
    }

    // Pool: track a batch of allocations, then bulk-free them all in one
    // call with free_pool().
    mut pool: mem::Pool = mem::Pool();
    test::assert(pool.length() == 0, "a fresh pool tracks nothing");

    mut i: int = 0;
    while i < 20 {
        pool.track(mem::alloc(16));
        i = i + 1;
    }
    test::assert(pool.length() == 20, "pool must track every allocation, including across growth");

    mem::free_pool(pool);

    io::printline("mem.tr Pool and aligned-allocation additions work");
    return 0;
}

// Regression test (issue #238): `unsafe { }` + `&T` safe references, end
// to end. Covers the legal counterparts to the four fail_*.tr tests in
// this same directory (fail_ptr_outside_unsafe.tr,
// fail_cast_raw_pointer_outside_unsafe.tr,
// fail_struct_raw_ptr_field_outside_unsafe.tr,
// fail_fn_signature_raw_pointer_disallowed.tr): a raw pointer declaration/
// cast/struct field, each properly `unsafe { }`-wrapped, plus `&T` used
// exactly as the roadmap's own example shows -- a compiler-guaranteed
// non-null reference, usable in an ordinary function signature with no
// `unsafe { }` needed at all.

import test;

// A raw pointer field requires the ENTIRE struct decl to be inside
// `unsafe { }` (FINAL_SPRINT.md's Track A) -- `next` is genuinely
// nullable, which `&Node` could never represent.
unsafe {
    struct Node {
        val: int,
        next: Node*
    }
}

func Node.new(val: int): void {
    self.val = val;
    unsafe {
        self.next = null;
    }
}

// A plain function's own signature never needs `unsafe { }` for a `&T`
// parameter/return -- only a RAW ptr/T* signature is disallowed outright.
fn readVal(n: &Node): int {
    return n.val;
}

fn main(): int {
    // `&val` (address-of) always produces `&int` now, a compiler-
    // guaranteed non-null reference -- no `unsafe { }` needed to declare
    // or use it.
    mutable val: int = 42;
    mutable ref: &int = &val;
    test::assert((ref == &val), "ref should alias val's address");

    // Declaring a raw pointer-typed local needs `unsafe { }` (the
    // "declaration" gate).
    unsafe {
        mutable p: ptr = null;
        test::assert(p == null, "raw ptr local can be null");
    }

    // Explicitly converting a safe reference to a raw pointer type (or
    // back) needs `unsafe { }` around the cast (the "cast" gate), even
    // though the safe-to-raw direction is otherwise implicitly allowed.
    unsafe {
        mutable asRaw: int* = ref to int*;
        test::assert(asRaw == &val, "explicit &T -> T* cast preserves the address");
    }

    // Constructing/chaining the unsafe-wrapped struct from above, and
    // reading a field THROUGH a raw pointer base (the "dereference" gate)
    // -- both need `unsafe { }`.
    mutable n1: Node = Node::new(1);
    mutable n2: Node = Node::new(2);
    n1.next = &n2; // &Node -> Node* is the always-sound safe-to-raw widening
    test::assert(unsafe { n1.next.val; } == 2, "field access through a raw pointer base");

    // A `&T`-typed function parameter needs no `unsafe { }` at either the
    // signature or an ordinary call site.
    test::assert(readVal(&n1) == 1, "readVal(&n1) should read n1.val");

    return 0;
}

// Regression test (LANG-004 item 2): `string` now coerces to a `ptr`
// parameter AT AN EXTERN FFI CALL SITE. Previously rejected outright:
// `extern fn puts(s: ptr): int32; puts("hi");` -> "No overload of 'puts'
// matches argument types (string)" -- even though `string` and `ptr`
// already share the identical LLVM representation (isPointerLike(),
// CodegenCore.cpp), so there was nothing to actually convert; it was
// purely a missing rule in TypeChecker argument matching
// (TypeCheckerCall.cpp's isExternStringToPtrCoercion(), gated on
// Cand->IsExtern so it never applies outside a real `extern fn` call).
//
// Covers both a string LITERAL argument and a runtime-BUILT string (via
// string `+` concatenation, lib/std/core/strings.tr's `operator +`), since
// a literal's type is trivially `string` at parse time but a concatenation
// result proves the coercion isn't somehow special-cased to literals only.

import test;

extern fn strlen(s: ptr): int;

fn main(): int {
    test::assert(strlen("hello") == 5, "string literal should coerce to ptr at an extern call site");

    var built: string = "hel" + "lo";
    test::assert(strlen(built) == 5, "a runtime-built string should coerce to ptr too, not just literals");

    return 0;
}

// Regression test: MEM-001's bare `gc_alloc`/`gc_alloc_zeroed`/`gc_realloc`
// intrinsics (docs/archive/ARCHITECTURE_OVERHAUL.md §8, src/sema/Intrinsics.h
// category 1) -- the Turf-visible surface for libturfrt's
// turf_rt_alloc/turf_rt_alloc_zeroed/turf_rt_realloc, exercised directly
// here rather than only indirectly through the stdlib call sites (strings.tr,
// list.tr, etc.) that were rerouted onto them. Every stdlib collection/string
// test already covers "does the reroute preserve behavior"; this file's job
// is "do the three intrinsics themselves do what their contract says",
// which nothing else specifically pins down.
//
// A `void*` local needs an `unsafe { }` block outside lib/std (the same
// caller-side-locals rule 17_mem_pool_and_aligned_alloc.tr's `aligned`
// local already exercises) -- these intrinsics are bare language keywords,
// not module-qualified calls, but their RESULT is still an ordinary raw
// `void*`, so the same gate applies to where it's bound.

import test;

fn main(): int {
    unsafe {
        // gc_alloc: a fresh, writable block of exactly the requested size.
        mut p: void* = gc_alloc(16);
        test::assert(p != null, "gc_alloc must return a non-null block");
        mut ip: int* = p to int*;
        ip[0] = 111;
        ip[1] = 222;
        test::assert(ip[0] == 111 && ip[1] == 222, "gc_alloc's block must be writable for its full requested size");

        // gc_alloc_zeroed: every byte starts at 0, unlike gc_alloc (which
        // makes no such promise). Checked via `char*` indexing (a raw byte
        // view) -- one already-nonzero byte written into the LAST slot
        // proves this isn't accidentally passing because the allocator
        // happened to hand back fresh, already-zero pages (glibc frequently
        // does for a first-ever large calloc, which would make this
        // assertion pass even from a non-zeroing gc_alloc).
        //
        // FDN-004: deliberately `char*`, not `string` -- this buffer is
        // all-zero bytes with one poisoned byte at the very end, i.e. it
        // has NO valid C-string length at all (`strlen()` would read 0)
        // until every byte before the poison is nonzero. `s[i]`'s new
        // bounds check is checked against `strlen(s)` (see
        // EmitStringBoundsCheck()'s doc comment, src/codegen/CodegenArray.cpp) --
        // exactly right for a real NUL-terminated string, but wrong for
        // inspecting a raw allocator block that isn't one. `char*` indexing
        // has no such check (same as any other raw pointer), which is what
        // this test actually wants.
        mut z: char* = gc_alloc_zeroed(8) to char*;
        z[7] = 9 to char; // poison the last byte so an all-zero pass can't be coincidental
        mut allZeroExceptLast: bool = true;
        mut i: int = 0;
        while i < 7 {
            if (z[i] to int) != 0 {
                allZeroExceptLast = false;
            }
            i = i + 1;
        }
        test::assert(allZeroExceptLast, "gc_alloc_zeroed must zero-fill every byte it returns");
        test::assert((z[7] to int) == 9, "writing into a gc_alloc_zeroed block must actually persist");

        // gc_realloc: preserves existing contents up to the smaller of the
        // two sizes, and the grown tail is genuinely usable (not just
        // "doesn't crash") -- exactly the contract list.tr/map.tr/etc.'s
        // growth call sites depend on.
        mut small: void* = gc_alloc(4 * 8); // room for 4 ints
        mut smallInts: int* = small to int*;
        smallInts[0] = 1;
        smallInts[1] = 2;
        smallInts[2] = 3;
        smallInts[3] = 4;

        mut grown: void* = gc_realloc(small, 8 * 8); // room for 8 ints
        mut grownInts: int* = (int)grown*;
        test::assert(grownInts[0] == 1 && grownInts[1] == 2 && grownInts[2] == 3 && grownInts[3] == 4,
            "gc_realloc must preserve every byte of the original allocation");
        grownInts[4] = 5;
        grownInts[5] = 6;
        grownInts[6] = 7;
        grownInts[7] = 8;
        test::assert(grownInts[4] == 5 && grownInts[7] == 8, "gc_realloc's grown tail must be genuinely writable");
    }

    return 0;
}

// LANG-002/STD-001: two things folded into this group from §15.8.
//
// F1 -- a module that declares the raw-pointer capability (`unsafe
// module;`, this file's first line) may write a `ptr`-taking function --
// what a C callback (`qsort`'s comparator, a signal handler, ...) requires.
// Before this group, `fn cmpints(a: ptr, b: ptr): int32` was rejected even
// inside `unsafe { }`, everywhere -- `checkNoRawPointersInSignature()` had
// no path to authorize it at all. `takesTwoRaw` below is exactly that
// previously-impossible shape.
//
// F2 -- "a second `extern fn` inside a top-level `unsafe { }` block fails
// to parse" was audited as a live parser bug (ARCHITECTURE_OVERHAUL.md
// §15.8). A direct repro against the current parser (several variants: with
// and without parameters, with and without `extern from "lib"`) did NOT
// reproduce it -- see docs/development/changes/LANG-002.md's own "Known
// pitfalls" for the verification. This test lock in the CORRECT behavior
// either way: two `extern fn`s inside one top-level `unsafe { }` block.
unsafe module;

unsafe {
    extern fn labs(x: int): int;
    extern fn atol(s: string): int;
}

fn takesTwoRaw(a: ptr, b: ptr): int32 {
    return 0 to int32;
}

fn main(): int {
    if (labs(-7) != 7) {
        return 1;
    }
    if (atol("42") != 42) {
        return 2;
    }
    unsafe {
        mut x: int = 1;
        mut y: bool = 2;
        if (takesTwoRaw(&x to ptr, &y to ptr) != 0) {
            return 3;
        }
    }
    return 0;
}

// `give`/`otherwise` as an array literal's element, and indexing a ternary
// whose arms are arrays (found by turf-fuzz). Codegen's own getExprType()
// had no case for the ternary, so the first shape aborted with "array
// literal element has no type" (a segfault before that guard) and the second
// with "Could not determine type of array/list base". The literal now takes
// its element type from the TypeChecker, and the ternary has the type of its
// arms.

import test;

fn first(p: int[2]): int {
    return p[0];
}

fn main(): int {
    mut c: int = 3;
    test::assert(first([(c > 2 give 3 otherwise 4), 5]) == 3, "as a call argument");

    mut b: int[2] = [0, 0];
    b = [(c < 2 give 3 otherwise 4), 5];
