// Regression test (was DISCOVERED_ISSUES.md #22, "Methods Cannot Return
// self"): a struct method CAN return self as a reference (`: &Node`) and
// this supports real method chaining -- `self.next.next` style traversal
// built entirely from methods, not just direct field access.
//
// (issue #238) `increment()`'s return type used to be `Counter*` (a raw
// pointer) -- a plain function may never return a raw ptr/T* type, even
// inside `unsafe { }` (see checkNoRawPointersInSignature()), so it now
// returns `&Counter` instead. `self`'s own synthesized type is still a raw
// `Counter*` under the hood (unchanged by this issue -- see
// TypeCheckerCall.cpp's `self`-exemption comment), so converting it to the
// declared `&Counter` return type is the raw-to-safe direction, which
// always needs an explicit cast inside `unsafe { }` -- self is always
// non-null by construction, so this is exactly the sound, narrow use the
// escape hatch exists for.
//
// By-value self-return is `return self to Node;`
// (24_self_value_return_and_chaining.tr): a bare `return self;` is E064.
// This file covers the by-reference half, the idiomatic way to chain method
// calls.

import test;

struct Counter {
    val: int
}

// Mutates self and returns self by reference, enabling chained calls.
fn Counter.increment(): &Counter {
    self.val = self.val + 1;
    unsafe {
        return self to &Counter;
    }
}

fn Counter.get(): int {
    return self.val;
}

fn main(): int {
    mut c: Counter = Counter{};

    // Single call returns a usable reference.
    mut p: &Counter = c.increment();
    test::assert(p.val == 1, "");
    test::assert(c.val == 1, "");

    // Chained calls: increment().increment().increment()
    c.increment().increment().increment();
    test::assert(c.val == 4, "");

    // Chained call ending in a read via .get()
    test::assert(c.increment().get() == 5, "");
    test::assert(c.val == 5, "");

    return 0;
}

// A struct method returns `self` BY VALUE (`fn Node.get_self(): Node`, not
// just `: Node*`) by copying it out: `return self to Node;`. `self` is the
// receiver's address (typed `Node*`), and a value leaves a reference only
// through an explicit `to`, so the copy is visible where it happens. The
// returned value is a copy, not an alias, and it chains like any value.
// Method-return-by-pointer for chaining is
// tests/06_structs/23_self_pointer_chaining.tr.

import test;

struct Node {
    val: int
}

fn Node.new(val: int): void {
    self.val = val;
}

fn Node.get_self(): Node {
    return self to Node;
}

fn main(): int {
    mut n: Node = Node::new(42);

    // Chaining method calls on a returned-by-value struct instance.
    test::assert(n.get_self().get_self().val == 42, "");

    // The returned value is a genuine by-value COPY, not an alias: mutating
    // the original afterward must not affect a variable holding the copy.
    let mut copy: Node = n.get_self();
    test::assert(copy.val == 42, "");
    n.val = 999;
    test::assert(copy.val == 42, "");
    test::assert(n.val == 999, "");

    return 0;
}

