// Test: Short-circuit evaluation for && (and) operator
// The right-hand side should NOT be evaluated if left is false

import io;

import test;
fn main(): int {
    // Counter to track RHS evaluation
    mut calls: int = 0;

    // For && (and): if LHS is false, RHS must NOT be evaluated
    // We simulate this by checking a variable that would only change if RHS runs

    // Test 1: false && anything == false (short-circuit, RHS skipped)
    mut x: int = 0;
    auto result1 = false && (x == 0);
    test::assert(result1 == false, "false && ... should be false");

    // Test 2: true && true == true (both sides evaluated)
    mut result2: bool = true && true;
    test::assert(result2 == true, "true && true should be true");

    // Test 3: true && false == false
    mut result3: bool = true && false;
    test::assert(result3 == false, "true && false should be false");

    // Test 4: false && false == false
    mut result4: bool = false && false;
    test::assert(result4 == false, "false && false should be false");

    // Test 5: Short-circuit with side-effecting condition
    // If && short-circuits, "a == 0" block won't execute
    mut a: int = 5;
    mut cond_a: bool = (a > 10) && (a == 5);  // LHS is false -> short-circuit
    test::assert(cond_a == false, "Short-circuit: (a > 10) && (a == 5) should be false");

    // Test 6: Chained && short-circuit
    mut b: int = 3;
    mut cond_b: bool = true && (b == 3) && (b < 10);
    test::assert(cond_b == true, "true && (b == 3) && (b < 10) should be true");

    // Test 7: && with complex expressions
    mut c: int = 42;
    mut d: int = 0;
    mut cond_c: bool = (d == 0) && (c > 0);  // both true
    test::assert(cond_c == true, "(d == 0) && (c > 0) should be true");

    // Test 8: && short-circuits — second operand not evaluated if first is false
    mut e: int = 0;
    // If short-circuit didn't work, dividing by e would crash
    mut cond_e: bool = (e != 0) && (100 / e > 5);
    test::assert(cond_e == false, "Short-circuit prevents div by zero: (e != 0) && (100/e > 5)");

    return 0;
}

// Test: Compound-assignment forms of the bitwise/shift operators (&=, |=,
// ^=, <<=, >>=). Only the plain binary forms (&, |, ^, <<, >>) existed
// before -- there was no way to write `x &= mask;` instead of the more
// verbose `x = x & mask;`, unlike the arithmetic operators which already had
# += -= *= /= %=. Mirrors 09_acceptance_criteria.tr's values so each result
// here is directly checkable against the plain-operator acceptance test.

import test;

fn main(): int {
    mut a: int = 5;
    a &= 3;
    test::assert(a == 1, "5 &= 3 should equal 1 (same as 5 & 3)");

    mut b: int = 5;
    b |= 3;
    test::assert(b == 7, "5 |= 3 should equal 7 (same as 5 | 3)");

    mut c: int = 5;
    c ^= 3;
    test::assert(c == 6, "5 ^= 3 should equal 6 (same as 5 ^ 3)");

    mut d: int = 1;
    d <<= 4;
    test::assert(d == 16, "1 <<= 4 should equal 16 (same as 1 << 4)");

    mut e: int = 256;
    e >>= 2;
    test::assert(e == 64, "256 >>= 2 should equal 64 (same as 256 >> 2)");

    // Chained on the same variable, left to right (each op reads the
    // variable's CURRENT value, not its original one).
    mut f: int = 255;
    f &= 15;                  // 255 & 15  = 15
    f |= 48;                  // 15  | 48  = 63
    f ^= 15;                  // 63  ^ 15  = 48
    f <<= 1;                  // 48  << 1  = 96
    f >>= 2;                  // 96  >> 2  = 24
    test::assert(f == 24, "chained bitwise compound-assign should equal 24");

    return 0;
}

// Test: Compound exponentiation assignment (**=). Unlike the bitwise
// compound-assign forms in 12_bitwise_compound_assignment.tr, `**=` is not
// restricted to int -- it follows the same "numeric operands, double
// intermediate" rule as the plain `**` operator (see 07_exponentiation.tr),
// but must narrow the result back down to the LHS's own declared type for
// the store (an int LHS keeps its declared type after `**=`, it doesn't
// silently become a double).

import test;

fn main(): int {
    mut a: double = 2.0;
    a **= 8.0;
    test::assert(a == 256.0, "2.0 **= 8.0 should equal 256.0");

    // int LHS: the double llvm.pow() result must be narrowed back to int
    // for the store, not left as a double (which would be a type/ABI bug --
    // `a`'s alloca is 8-byte int-typed storage, not double-typed).
    mut b: int = 3;
    b **= 4;
    test::assert(b == 81, "3 **= 4 (narrowed back to int) should equal 81");

    // Fractional exponent on an int base still goes through the double
    // pow() path internally, then narrows: 9 ** 0.5 == 3.0, truncated to 3.
    mut c: int = 9;
    c **= 2;
    test::assert(c == 81, "9 **= 2 should equal 81");

    // RHS need not match LHS's type -- an int LHS with a double exponent is
    // valid (same numeric-coercion rule as every other compound assignment).
    mut d: int = 2;
    mut epx: double = 3.0;
    d **= exp;
    test::assert(d == 8, "2 **= 3.0 (double RHS, int LHS) should equal 8");

    return 0;
}

