// tests/13_string_stdlib/13_dsa_count_words.tr
// DSA: Word count tokenizer — counts space-delimited tokens in a string.
// Exercises: char access, strings::length, loops, boundary detection.

import io;
import strings;

import test;
// Count the number of whitespace-delimited words in `s`.
fn count_words(s: string): int {
    mut n: int = strings::length(s);
    mut count: int = 0;
    mut in_word: bool = false;
    mut i: int = 0;
    while i < n {
        // FDN-004/D17: `s[i]` is `char`; widen to `int` before comparing.
        mut c: int = s[i] to int;
        // space=32, tab=9, newline=10
        var is_space: bool = (c == 32 || c == 9 || c == 10);
        if is_space {
            in_word = false;
        } else {
            if in_word == false {
                count = count + 1;
                in_word = true;
            }
        }
        i = i + 1;
    }
    return count;
}

fn main(): int {
    test::assert(count_words("hello world") == 2,          "two words");
    test::assert(count_words("one two three") == 3,        "three words");
    test::assert(count_words("  leading spaces") == 2,     "leading spaces ignored");
    test::assert(count_words("trailing spaces  ") == 2,    "trailing spaces ignored");
    test::assert(count_words("  multiple   spaces  ") == 2,"multiple spaces between words");
    test::assert(count_words("single") == 1,               "single word");
    test::assert(count_words("") == 0,                     "empty string has 0 words");
    test::assert(count_words("   ") == 0,                  "all spaces has 0 words");

    // Longer sentence
    test::assert(count_words("the quick brown fox jumps over the lazy dog") == 9, "9-word sentence");

    io::printline("13 PASS: DSA word count tokenizer");
    return 0;
}

// tests/13_string_stdlib/15_dsa_reverse_string_recursive.tr
// DSA: Recursive string reversal via character concatenation.
// Stresses the call stack and strings::length + char access together.
// Also verifies that double reversal returns the original.

import io;
import strings;

import test;
fn reverse(string s): string {
    mut n: int = strings::length(s);
    if n <= 1 {
        return s;
    }
    // Head character as a 2-byte string
    mut tail: string = reverse(strings::substring(s, 1, n));
    mut head_ch: string = strings::substring(s, 0, 1);
    return tail + head_ch;
}

fn main(): int {
    test::assert(reverse("hello") == "olleh",          "reverse hello");
    test::assert(reverse("abcd") == "dcba",            "reverse abcd");
    test::assert(reverse("a") == "a",                  "reverse single char");
    test::assert(reverse("") == "",                    "reverse empty");
    test::assert(reverse("racecar") == "racecar",      "reverse palindrome == itself");

    // Double reversal must return original
    mut original: string = "turf language";
    test::assert(reverse(reverse(original)) == original, "double reverse == original");

    io::printline("15 PASS: DSA recursive string reverse");
    return 0;
}

// tests/13_string_stdlib/18_str_split_join.tr
// Tests strings::split and strings::join, including the two documented
// edge cases: empty delimiter (no-op, whole string as one piece) and no
// match at all (also whole string as one piece).

import io;
import strings;
import list::List;

import test;
fn main(): int {
    // Basic split
    mut parts: List<string> = strings::split("a,b,c", ",");
    test::assert_eq(parts.length(), 3, "split: 'a,b,c' on ',' -> 3 parts");
    test::assert(parts.get(0) == "a", "split: part 0 == 'a'");
    test::assert(parts.get(1) == "b", "split: part 1 == 'b'");
    test::assert(parts.get(2) == "c", "split: part 2 == 'c'");

    // Multi-byte delimiter
    mut parts2: List<string> = strings::split("one::two::three", "::");
    test::assert_eq(parts2.length(), 3, "split: multi-byte delimiter -> 3 parts");
    test::assert(parts2.get(0) == "one", "split: multi-byte part 0");
    test::assert(parts2.get(1) == "two", "split: multi-byte part 1");
    test::assert(parts2.get(2) == "three", "split: multi-byte part 2");

    // No match at all -> single-element list containing the whole string
    mut noMatch: List<string> = strings::split("hello", ",");
    test::assert_eq(noMatch.length(), 1, "split: no delimiter present -> 1 part");
    test::assert(noMatch.get(0) == "hello", "split: no delimiter present -> whole string");

    // Empty delimiter -> single-element list containing the whole string
    mut emptyDelim: List<string> = strings::split("hello", "");
    test::assert_eq(emptyDelim.length(), 1, "split: empty delimiter -> 1 part (no-op)");
    test::assert(emptyDelim.get(0) == "hello", "split: empty delimiter -> whole string");

    // Empty string input
    mut emptyInput: List<string> = strings::split("", ",");
    test::assert_eq(emptyInput.length(), 1, "split: empty input -> 1 (empty) part");
    test::assert(emptyInput.get(0) == "", "split: empty input -> empty part");

    // Adjacent delimiters produce empty pieces
    mut adjacent: List<string> = strings::split("a,,b", ",");
    test::assert_eq(adjacent.length(), 3, "split: adjacent delimiters -> 3 parts");
    test::assert(adjacent.get(0) == "a", "split: adjacent part 0");
    test::assert(adjacent.get(1) == "", "split: adjacent part 1 empty");
    test::assert(adjacent.get(2) == "b", "split: adjacent part 2");

    // Leading/trailing delimiter
    mut leading: List<string> = strings::split(",a,b", ",");
    test::assert_eq(leading.length(), 3, "split: leading delimiter -> 3 parts");
    test::assert(leading.get(0) == "", "split: leading delimiter -> first part empty");

    // join: inverse of split
    test::assert(strings::join(parts, ",") == "a,b,c", "join: inverse of split");
    test::assert(strings::join(adjacent, ",") == "a,,b", "join: round-trip with empty piece");

    // join with a single-element list -> no separator inserted
    test::assert(strings::join(noMatch, ",") == "hello", "join: single element -> no separator");

    printf("18 PASS: strings::split / strings::join");
    return 0;
}

