// Test: compare statement with all variants covered + otherwise — no error
import test;

enum Season { Spring, Summer, Autumn, Winter }

fn season_name(s: Season): string {
    mut name: string = "";
    compare s {
        case Season::Spring:
        name = "spring";
        done
        matches Season::Summer:
        name = "summer";
        done
        matches Season::Autumn:
        name = "cold";
        done
        matches Season::Winter:
        name = "cold";
        done
    }
    return name;
}

fn season_name_with_otherwise(s: Season): string {
    mut name: string = "";
    compare s {
        matches Season::Spring:
        name = "spring";
        done
        matches Season::Summer:
        name = "summer";
        done
        otherwise:
        name = "cold";
    }
    return name;
}

fn main(): int {
    test::assert(season_name(Season::Spring) == "spring", "Spring name");
    test::assert(season_name(Season::Summer) == "summer", "Summer name");
    test::assert(season_name(Season::Autumn) == "cold",   "Autumn name");
    test::assert(season_name(Season::Winter) == "cold",   "Winter name");

    test::assert(season_name_with_otherwise(Season::Spring) == "spring", "Spring otherwise");
    test::assert(season_name_with_otherwise(Season::Autumn) == "cold",   "Autumn falls to otherwise");
    test::assert(season_name_with_otherwise(Season::Winter) == "cold",   "Winter falls to otherwise");
    return 0;
}

// Test: Pass enum as function parameter and return from function
import test;

enum Priority { Low, Medium, High, Critical }

fn is_urgent(p: Priority): bool {
    compare p {
        matches Priority::High:
        return true;
        break;
        matches Priority::Critical:
        return true;
        done
        matches Priority::Low:
        return false;
        done
        matches Priority::Medium:
        return false;
        done
    }
    return false;
}

fn escalate(p: Priority): Priority {
    compare p {
        matches Priority::Low:
        return Priority::Medium;
        done
        matches Priority::Medium:
        return Priority::High;
        done
        matches Priority::High:
        return Priority::Critical;
        done
        matches Priority::Critical:
        return Priority::Critical;
        done
    }
    return Priority::Critical;
}

fn main(): int {
    test::assert(is_urgent(Priority::Low) == false, "Low is not urgent");
    test::assert(is_urgent(Priority::Medium) == false, "Medium is not urgent");
    test::assert(is_urgent(Priority::High) == true, "High is urgent");
    test::assert(is_urgent(Priority::Critical) == true, "Critical is urgent");

    test::assert((escalate(Priority::Low) to int) == 1, "Low escalates to Medium");
    test::assert((escalate(Priority::Medium) to int) == 2, "Medium escalates to High");
    test::assert((escalate(Priority::High) to int) == 3, "High escalates to Critical");
    test::assert((escalate(Priority::Critical) to int) == 3, "Critical stays Critical");
    return 0;
}

