enum Color { Red, Green, Blue, Yellow }

fn classify(c: Color): string {
    mut name: string = "";
    compare c {
        matches Color::Red:
        matches Color::Yellow:
        name = "warm";
        break;
        matches Color::Green:
        matches Color::Blue:
        name = "cool";
        done
    }
    return name;
}

fn main(): int {
