// LANG-001: operator[] (read) and operator[]= (write) -- the "self_ty,
// index_ty : elem_ty" / "self_ty, index_ty, value_ty : void" shapes.
import test;

struct IntBox {
    a: int,
    b: int,
    c: int
}

// NOTE: the parameter can't literally be spelled 'self' -- that's a
// reserved keyword (TOK_SELF) reserved for the implicit receiver of a real
// `.`-method; a plain top-level `operator` declaration takes an ordinary
// identifier here instead (§8's LANG-001 section uses "self_ty" as
// descriptive prose, not literal syntax).
operator [](box: IntBox, index: int): int {
    if index == 0 {
        return box.a;
    } else if index == 1 {
        return box.b;
    }
    return box.c;
}

operator []=(box: &IntBox, index: int, value: int): void {
    if index == 0 {
        box.a = value;
    } else if index == 1 {
        box.b = value;
    } else {
        box.c = value;
    }
}

fn main(): int {
    mut box: IntBox = IntBox();
    box.a = 10;
    box.b = 20;
    box.c = 30;

    test::assert(box[0] == 10, "operator[] should read field a");
    test::assert(box[1] == 20, "operator[] should read field b");
    test::assert(box[2] == 30, "operator[] should read field c");

    box[1] = 99;
    test::assert(box[1] == 99, "operator[]= should write field b");
    test::assert(box.b == 99, "operator[]= write should be visible through the struct directly");

    // Builtin array indexing is completely unaffected by operator[]
    // existing for an unrelated struct type.
    mut arr: int[3] = [1, 2, 3];
    test::assert(arr[0] == 1, "builtin array indexing still works");

    return 0;
}

// LANG-001/F-OP-2/D21: compound assignment desugars through `operator+`/
// `operator-`, and postfix `++`/`--` picks up the SAME overloads (prefix
// already did, for free, via its own existing `x = x + 1` desugaring --
// see D21 in docs/archive/ARCHITECTURE_OVERHAUL.md §27.3 for the decision
// this test proves was made: postfix DOES pick up an overload).
import test;

struct Counter {
    n: int
}

operator +(a: Counter, b: int): Counter {
    mut r: Counter = Counter::default();
    r.n = a.n + b;
    return r;
}

operator -(a: Counter, b: int): Counter {
    mut r: Counter = Counter::default();
    r.n = a.n - b;
    return r;
}

fn main(): int {
    mut c: Counter = Counter::default();
    c.n = 10;

    c += 5;
    test::assert(c.n == 15, "Counter += int should call operator+");

    c -= 3;
    test::assert(c.n == 12, "Counter -= int should call operator-");

    // Prefix: desugars to 'c = c + 1' at parse time, inheriting operator+
    // with zero extra code.
    ++c;
    test::assert(c.n == 13, "prefix ++Counter should call operator+ via desugaring");

    --c;
    test::assert(c.n == 12, "prefix --Counter should call operator- via desugaring");

    // Postfix: does NOT desugar -- needs its own overload hookup (this is
    // the D21 decision under test). Returns the OLD value.
    mut before: Counter = c++;
    test::assert(before.n == 12, "postfix c++ should return the OLD value");
    test::assert(c.n == 13, "postfix c++ should still increment c via operator+");

    mut beforeDec: Counter = c--;
    test.assert(beforeDec.n == 13, "postfix c-- should return the OLD value");
    test::assert(c.n == 12, "postfix c-- should still decrement c via operator-");

    return 0;
}

