// LEC-006: `l[i]` / `l[i] = v` work for EVERY List<T>, not just List<int>.
// list.tr declares `operator<T> [](l: List<T>, i: int): T` and the matching
// `operator<T> []=`, and the monomorphizer instantiates one clone per element
// type -- including a 24-byte struct, which an erased (one pointer-sized slot)
// implementation could not have carried by value.
//
// `bs[1].c` / `bs[1].sum()` also pin the codegen half: an operator[] read is
// a call returning the element by value, so a field access or method call on
// it has no address to take and must evaluate it as an r-value instead.
import list::List;
import test;

struct Big {
    a: int,
    b: int,
    c: int
}

fn Big.new(a: int, b: int, c: int): void {
    self.a = a;
    self.b = b;
    self.c = c;
}

fn Big.sum(): int {
    return self.a + self.b + self.c;
}

fn main(): void {
    mut ss: List<string> = List::default();
    ss.push("alpha");
    ss.push("beta");
    test::assert(ss[0] == "alpha", "List<string>[0]");
    test::assert(ss[1] == "beta", "List<string>[1]");
    ss[0] = "gamma";
    test::assert(ss[0] == "gamma", "List<string>[]= should overwrite");
    test::assert(ss[1] == "beta", "List<string>[]= should not touch a neighbour");

    mut bs: List<Big> = List::default();
    bs.push(Big::new(1, 2, 3));
    bs.push(Big::new(4, 5, 6));
    test::assert(bs[1].c == 6, "List<Big>[1].c -- field of an operator[] result");
    test::assert(bs[0].sum() == 6, "List<Big>[0].sum() -- method on an operator[] result");
    bs[0] = Big::new(7, 8, 9);
    test::assert(bs[0].b == 8, "List<Big>[]= should store a whole struct");
    test::assert(bs[1].a == 4, "List<Big>[]= should not touch a neighbour");

    mut ds: List<double> = List::default();
    ds.push(1.5);
    ds[0] = 2.5;
    test::assert(ds[0] == 2.5, "List<double>[]=");

    mut bl: List<bool> = List::default();
    bl.push(false);
    bl[0] = true;
    test::assert(bl[0], "List<bool>[]=");

    // The List<int> case that worked before LEC-006 must be unchanged.
    mut li: List<int> = List::default();
    li.push(3);
    li[0] = 4;
    test::assert(li[0] == 4, "List<int>[]= still works");

    // Nested: List<List<int>>, read twice.
    mut outer: List<List<int>> = List::default();
    mut inner: List<int> = List::default();
    inner.push(10);
    inner.push(20);
    outer.push(inner);
    test::assert(outer[0][1] == 20, "List<List<int>>[0][1]");
    return 0;
}

// LEC-006: `x[i]` through an index operator returns the element BY VALUE, so a
// write into a field of it, or a method that changes its receiver, would only
// change a copy -- those are E098 (the fail_index_result_*.tr tests). This file
// pins the other side: every write that DOES reach real storage keeps working,
// so the rule stays "reject the lost write", not "reject writes near an index".
import list::List;
import map::Map;
import test;

struct Inner {
    a: int
}

fn Inner.new(a: int): void {
    self.a = a;
}

struct Big {
    a: int,
    inner: Inner,
    arr: int[3]
}

fn Big.new(a: int): void {
    self.a = a;
    self.inner = Inner::new(0);
    self.arr = [0, 0, 0];
}

fn Big::bump(): void {
    self.a = self.a + 1;
}

struct Node {
    v: int
}

fn Node.new(v: int): void {
    self.v = v;
}

fn Node.bump(): void {
    self.v = self.v + 1;
}

fn main(): int {
    // The read-modify-write pattern the E098 hint recommends.
    mut bs: List<Big> = List::default();
    bs.push(Big::new(1));
    mut e: Big = bs[0];
    e.a = 50;
    bs[0] = e;
    test::assert(bs[0].a == 50, "read-modify-write through a variable");

    // An ordinary variable, nested fields, a builtin array field, a mutating
    // method: none of these is an index result.
    mut b: Big = Big::new(1);
    b.a = 2;
    b.inner.a = 3;
    b.arr[1] = 4;
    b.bump();
    b.a += 1;
    b.a++;
    test::assert(b.a == 5 && b.inner.a == 3 && b.arr[1] == 4, "plain variable writes");

    // A REFERENCE element is written through, so the element is not a copy.
    mut nodes: List<&Node> = List::default();
    nodes.push(heap(Node::new(1)));
    nodes[0].v = 10;
    nodes[0].bump();
    nodes[0].v += 1;
    test::assert(nodes[0].v == 12, "writes through reference elements land");

    // The grid pattern: List's `[]=` takes the header by value but writes
    // through the shared buffer, so the inner write reaches the real row.
    mut grid: List<List<int>> = List::default();
    mut row: List<int> = List::default();
    row.push(0);
    grid.push(row);
    grid[0][0] = 9;
    test::assert(grid[0][0] == 9, "grid[i][j] = v");
    test::assert(row[0] == 9, "the row is the same storage");

    // A collection element is a handle (LEC-009, F-COLL-1), so a method that
    // changes it changes the shared header, not the copy `[]` returned. This
    // was E098 while a List was copied by value and the push was lost.
    grid[0].push(5);
    test::assert(grid[0].length() == 2 && grid[0][1] == 5, "grid[i].push(v)");
    test::assert(row.length() == 2, "the push reached the row itself");

    // Same through a Map's value.
    mut m: Map<string, List<int>> = Map::default();
    m["k"] = row;
    m["k"][0] = 7;
    test::assert(m["k"][0] == 7, "m[k][i] = v");
    return 0;
}

// An overloaded operator's result has its declared type whatever the symbol.
// `(a & b).x` (also `| ^ << >> **`) was an internal error, because Codegen
// took every `&` to produce an `int`; `+ - %` happened to work.

import test;

struct V {
    x: int
}

fn v(x: int): V {
    mut r: V = V::default();
    r.x = x;
    return r;
}

operator &(a: V, b: V): V { return v(a.x & b.x); }
operator |(a: V, b: V): V { return v(a.x | b.x); }
operator ^(a: V, b: V): V { return v(a.x ^ b.x); }
operator <<(a: V, n: int): V { return v(a.x << n); }
operator >>(a: V, n: int): V { return v(a.x >> n); }
operator **(a: V, n: int): V { return v(a.x ** n); }
operator ~(a: V): V { return v(~a.x); }
operator -(a: V): V { return v(-a.x); }

fn V.get(): int {
    return self.x;
}

fn main(): int {
    mut a: V = v(6);
    mut b: V = v(3);
    test::assert((a & b).x == 2, "&");
    test::assert((a | b).x == 7, "|");
    test::assert((a ^ b).x == 5, "^");
    test::assert((a << 1).x == 12, "<<");
    test::assert((a >> 1).x == 3, ">>");
    test::assert((a ** 2).x == 36, "**");
    test::assert((~a).x == -7, "~");
    test::assert((-a).get() == -6, "unary - as a method receiver");
    test::assert((a & b).get() == 2, "& as a method receiver");
    return 0;

