// Map::try_get (lib/std/map.tr) -- the recoverable alternative to get(),
// which hard-panics on a missing key. Exercises a GENERIC function
// returning `!V` (V is Map's own type parameter, substituted to a concrete
// type at the call site -- see the generic-substitution fix this depends
// on), both success and failure paths, and `recover as err` distinguishing
// MapError::KeyNotFound. Each `recover as err` scenario lives in its own
// helper function since a diverging `return` inside the recover block
// returns from the ENCLOSING function, not just the recover expression.
import test;
import map::Map;

fn buildMap(): Map<string, int> {
    mut m: Map<string, int> = Map();
    m.put("a", 1);
    m.put("b", 2);
    return m;
}

fn tryGetExisting(): int {
    mut m: Map<string, int> = buildMap();
    return m.try_get("b") recover as err run {
        return -1;
    };
}

fn tryGetMissing(): int {
    mut m: Map<string, int> = buildMap();
    return m.try_get("missing") recover as err run {
        if err == map::MapError::KeyNotFound {
            return -3;
        }
        return -4;
    };
}

fn main(): int {
    mut m: Map<string, int> = buildMap();

    mut x: int = m.try_get("a") recover produce -1;
    test::assert_eq(x, 1, "try_get on an existing key should succeed with the real value");

    mut y: int = m.try_get("nope") recover produce -1;
    test::assert_eq(y, -1, "try_get on a missing key should recover instead of aborting");

    test::assert_eq(tryGetExisting(), 2, "success path should never touch the recover-as-err block");
    test::assert_eq(tryGetMissing(), -3, "failure path should correctly identify MapError::KeyNotFound");

    return 0;
}

// Regression test: `!T`'s boxed successBits slot (see BoxToI64Slot()/
// UnboxFromI64Slot() in Codegen.cpp) must round-trip every kind of Turf
// value correctly, not just the int/void cases the earlier tests happened
// to cover. Added after a user question about whether the struct case
// (09_recover_struct_success.tr) was really exercising what it claimed to
// -- prompted widening coverage across the rest of the primitive/struct
// matrix rather than trusting that one shape generalizes.
import test;
import math;

error MyError {
    Failed,
}

fn getString(shouldFail: bool): !string {
    if (shouldFail) { return MyError::Failed; }
    return "hello world";
}

fn getBool(shouldFail: bool): !bool {
    if (shouldFail) { return MyError::Failed; }
    return true;
}

fn getChar(shouldFail: bool): !char {
    if (shouldFail) { return MyError::Failed; }
    return 'Z';
}

fn getInt32(shouldFail: bool): !int32 {
    if (shouldFail) { return MyError::Failed; }
    return 99 to int32;
}

struct Person {
    name: string,
    int age;
}
fn Person.new(name: string, age: int): void {
    self.name = name;
    self.age = age;
}
fn getPerson(shouldFail: bool): !Person {
    if (shouldFail) { return MyError::Failed; }
    return Person::new("Ada", 36);
}

fn main(): int {
    // string
    mut s: string = getString(false) recover produce "fallback";
    test::assert(s == "hello world", "string success value should round-trip correctly");
    mut s2: string = getString(true) recover produce "fallback";
    test::assert(s2 == "fallback", "string failure should produce the replacement");

    // bool
    mut b: bool = getBool(false) recover produce false;
    test::assert_eq(b, true, "bool success value should round-trip correctly");
    mut b2: bool = getBool(true) recover produce false;
    test::assert_eq(b2, false, "bool failure should produce the replacement");

    // char
    mut c: char = getChar(false) recover produce 'x';
    test::assert(c == 'Z', "char success value should round-trip correctly");
    mut c2: char = getChar(true) recover produce 'x';
    test::assert(c2 == 'x', "char failure should produce the replacement");

    // int32
    mut n: int32 = getInt32(false) recover produce (1 to int32);
    test::assert_eq(n to int, 99, "int32 success value should round-trip correctly");
    mut n2: int32 = getInt32(true) recover produce (1 to int32);
    test::assert_eq(n2 to int, 1, "int32 failure should produce the replacement");

    // struct with a STRING field (not just ints, unlike 09's Point) --
    // the heap-boxed slot must preserve internal pointer fields correctly.
    mut p: Person = getPerson(false) recover run {
        return -1;
    };
    test::assert(p.name == "Ada", "struct-with-string-field success value should round-trip: name");
    test::assert_eq(p.age, 36, "struct-with-string-field success value should round-trip: age");

    // recover used directly as a function-call argument, not just a plain
    // var-decl initializer -- a different codegen context (nested inside
    // another expression's arg-evaluation) than every other test here.
    test::assert_eq(math::divide(20, 4) recover produce -1, 5, "recover works as a direct function-call argument");

    return 0;
}

// Regression test: `recover produce <StructValue>` as a guaranteed-fallback
// mechanism for a struct success type. Added after a user question about
// `recover run { return -1; }` against a `!Point` call: that `-1` is main's
// own return value on a path that abandons the assignment entirely -- it is
// never a Point, and `p` gets no value at all on that path. `recover produce`
// is the actual tool for "the variable always ends up with a real Point,"
// so this test proves that both the success path AND the produced-fallback
// path give `p` a genuine, correctly-populated Point -- never a placeholder,
// zeroed, or partially-constructed one.
import test;

error MyError {
    Failed,
}

struct Point {
    x: int,
    y: int,
}

fn Point.new(x: int, y: int): void {
    self.x = x;
    self.y = y;
}

fn makePoint(shouldFail: bool): !Point {
    if (shouldFail) {
        return MyError::Failed;
    }
    return Point::new(42, 7);
}

fn main(): int {
    mut p: Point = makePoint(false) recover produce new Point(0, 0);
    test::assert_eq(p.x, 42, "success path should keep the real Point, not the fallback");
    test::assert_eq(p.y, 7, "success path should keep the real Point, not the fallback");

    mut fallback: Point = makePoint(true) recover produce Point::new(0, 0);
    test::assert_eq(fallback.x, 0, "failure path should produce the real fallback Point's first field");
    test::assert_eq(fallback.y, 0, "failure path should produce the real fallback Point's second field");

    return 0;
}

// STD-002 (ARCHITECTURE_OVERHAUL.md §8/§15.6(c)): `ErrorType::Variant(
// messageExpr)` -- exactly one 'string' argument, attaching a message to
// this specific error occurrence, readable back via `err.message` inside
// `recover as err run { ... }`. Exercises a RUNTIME-COMPUTED message (not
// a literal -- string concatenation), a bare (message-less) variant's
// `.message` reading back as empty, and equality (`err == Variant`) still
// correctly identifying the variant regardless of which message it
// carries.
import test;
import strings;

error MathError {
    DivisionByZero,
    NegativeSqrt,
}

fn divide(a: int, b: int): !int {
    if b == 0 {
        return MathError::DivisionByZero("division by " + (str(a)) + "/0");
    }
    return a / b;
}

fn bareFail(): !int {
    return MathError::NegativeSqrt;
}

fn main(): int {
    mut msg: string = "";
    divide(10, 0) recover as err run {
        msg = err.message;
        return 0;
    };
    test::assert_eq(msg, "division by 10/0",
        "a message built from RUNTIME string concatenation round-trips through construction, !T, and .message");

    mut bareMsg: string = "not empty yet";
    bareFail() recover as err run {
        bareMsg = err.message;
        return 0;
    };
    test::assert_eq(bareMsg, "", "a bare (message-less) variant's .message reads back as empty, not garbage");

    divide(10, 0) recover as err run {
        test::assert(err == MathError::DivisionByZero,
            "equality still identifies the correct variant regardless of which message it carries");
        test::assert(!(err == MathError::NegativeSqrt),
            "equality correctly rejects the WRONG variant even though both are MathError");
        return 0;
    };

    return 0;
}

