// LEC-004 (FREEZE.md §6.18): an error variant may declare typed fields,
// constructed positionally and read back ONLY by a destructuring pattern
// inside a `compare`. Three shapes in one type: two fields, one field, none.
import io;
import test;

error IOError {
    NotFound(path: string),
    Denied(path: string, mode: int),
    Timeout
}

fn open(p: string, m: int): !int {
    if m == 0 { return IOError::NotFound(p); }
    if m == 1 { return IOError::Denied(p, 7); }
    if m == 2 { return IOError::Timeout; }
    return m;
}

// `return` inside a recover block returns from THIS function, so each read of a
// payload lives in a function that turns it into an int.
fn code(p: string, m: int): int {
    v := open(p, m) recover as err run {
        compare err {
            matches IOError::NotFound(path):
            test::assert(path == "a.txt", "NotFound carries its path");
            return 10;
            done
            matches IOError::Denied(path, mode):
            test::assert(path == "b.txt", "Denied carries its path");
            return 20 + mode;
            done
            matches IOError::Timeout:
            return 30;
            done
            otherwise:
            return 99;
        }
    };
    return v;
}

fn main(): int {
    test::assert(code("a.txt", 0) == 10, "NotFound(path)");
    test::assert(code("b.txt", 1) == 27, "Denied(path, mode) binds both fields, in order");
    test::assert(code("c.txt", 2) == 30, "a variant with no fields still matches by tag");
    test::assert(code("d.txt", 5) == 5, "success is untouched");
    io::printline("25/17 PASS");
    return 0;
}

// LEC-004: a variant pattern's sub-patterns are the ones a struct pattern's
// fields take: a name that binds, `_`, a literal, an enum variant, and a
// trailing `..`. Headers are tried in source order (LEC-003): a failing literal
// or guard falls through to the next header; stacked headers share bindings.
import io;
import test;

enum Mode { Read, Write }

error IOError {
    Denied(path: string, mode: int, kind: Mode),
    Closed(reason: string)
}

fn fail(m: int, k: Mode): !int {
    return IOError::Denied("p", m, k);
}

fn classify(m: int, k: Mode): int {
    immut v: int = fail(m, k) recover as err run {
        compare err {
            matches IOError::Denied(_, 0, _):
            return 1;
            done
            matches IOError::Denied(_, _, Mode::Write) if m > 100:
            return 2;
            done
            matches IOError::Denied(path, mode, Mode::Write):
            test::assert(path == "p", "binds a string");
            return 3 + mode;
            done
            matches IOError::Denied(_, mode, ..):
            return 50 + mode;
            done
            matches IOError::Closed(..):
            return 60;
            done
            otherwise:
            return 99;
        }
    };
    return v;
}

fn sharedBinding(flag: bool): int {
    immut v: int = failFlag(flag) recover as err run {
        compare err {
            matches IOError::Denied(why, _, _):
            matches IOError::Closed(why):
            return why == "shut" give 1 otherwise 2;
            done
            otherwise:
            return 99;
        }
    };
    return v;
}

fn failFlag(flag: bool): !int {
    if flag {
        return IOError::Closed("shut");
    }
    return IOError::Denied("opened", 1, Mode::Read);
}

fn main(): int {
    test::assert(classify(0, Mode::Read) == 1, "a literal sub-pattern tests a field");
    test::assert(classify(200, Mode::Write) == 2, "a guard can read a name from outside the pattern");
    test::assert(classify(5, Mode::Write) == 8, "a failing guard falls through to the next header");
    test::assert(classify(5, Mode::Read) == 55, "an enum-variant sub-pattern that fails falls through");
    test::assert(sharedBinding(True) == 1, "stacked headers share one binding (Closed)");
    test::assert(sharedBinding(false) == 2, "stacked headers share one binding (Denied)");
    io::printline("25/19 PASS");
    return 0;
}

// LEC-004 (DEC-11): `try <expr>` is prefix error propagation. On success it is
// the value; on failure it returns the error, unchanged, from the enclosing
// `!V` function. It binds like a prefix operator, so `try a() + try b()` is
// `(try a()) + (try b())`.
import io;
import test;

error MathError {
    Negative(value: int),
    TooBig(value: int, limit: int)
}

fn check(n: int): !int {
    if n < 0 { return MathError::Negative(n); }
    if n > 100 { return MathError::TooBig(n, 100); }
    return n;
}

fn sum(a: int, b: int): !int {
    return try check(a) + try check(b);
}

fn chain(a: int, b: int, c: int): !int {
    immut x: int = try check(a);
    immut y: int = try check(b);
    immut z: int = try check(c);
    return x + y + z;
}

fn describe(r: int, a: int, b: int): int {
    immut v: int = sum(a, b) recover as err run {
        compare err {
            matches MathError::Negative(v):
            return 0 - v;
            break;
            matches MathError::TooBig(v, limit):
            return v - limit;
            done
            otherwise:
            return 999;
        }
    };
    return v;
}

fn main(): int {
    test::assert(describe(0, 3, 4) == 7, "both operands succeed");
    test::assert(describe(0, 0 - 5, 4) == 5, "the first operand's error leaves the function");
    test::assert(describe(0, 4, 150) == 50, "the second operand's error leaves the function");
    immut ok: int = chain(1, 2, 3) recover produce -1;
    immut bad: int = chain(1, 200, 3) recover produce -1;
    test::assert(ok == 6, "three trys in a row");
    test::assert(bad == 0 - 1, "the middle one fails, the rest never run");
    io::printline("25/22 PASS");
    return 0;
}

