// LEC-004: `try` IS a return, so it runs the pending `defer`s exactly as
// `return` does -- in every open block, innermost first, LIFO -- before leaving.
// A `try` inside a loop leaves the whole function, not just the iteration.
import io;
import test;

error StopError {
    Stop(at: int)
}

struct Trail {
    log: string
}

fn Trail.new(): void {
    self.log = "";
}

fn advance(i: int): !int {
    if i == 3 { return StopError::Stop(i); }
    return i;
}

fn walk(t: &Trail, limit: int): !int {
    defer t.log = t.log + "F";
    mut total: int = 0;
    mut i: int = 0;
    while i < limit {
        defer t.log = t.log + "i";
        total = total + try advance(i);
        i = i + 1;
    }
    return total;
}

fn failedAt(t: &Trail, limit: int): int {
    const v: int = walk(t, limit) recover as err run {
        compare err {
            matches StopError::Stop(at):
            return at;
            done
            otherwise:
            return 99;
        }
    };
    return v;
}

fn main(): int {
    mut ok: Trail = Trail::new();
    immut total: int = walk(&ok, 3) recover produce -1;
    test::assert(total == 3, "0 + 1 + 2");
    test::assert(ok.log == "iiiF", "each iteration's defer, then the function's");

    mut bad: Trail = Trail::new();
    test::assert(failedAt(&bad, 10) == 3, "the error reaches the caller with its payload");
    test::assert(bad.log == "iiiiF",
        "iterations 0-2 finished, iteration 3's defer ran when `try` left, then the function's");
    io::printline("25/23 PASS");
    return 0;
}

// LEC-004: `try` returns the error value UNCHANGED -- same tag, same payload,
// same message -- through any number of levels, even across functions whose
// success types have nothing in common (the error union is open, so there is
// nothing to convert).
import io;
import test;

error DbError {
    Missing(table: string, id: int),
    Locked
}

fn fetch(id: int): !string {
    if id == 0 { return DbError::Missing("users", id, "no such user"); }
    if id == 1 { return DbError::Locked; }
    return "user-" + (id to string);
}

fn fetchLen(id: int): !int {
    immut s: string = try fetch(id);
    return strings::length(s);
}

fn fetchDouble(id: int): !double {
    immut n: int = try fetchLen(id);
    return (n to double) * 2.0;
}

fn fetchFlag(id: int): !bool {
    immut d: double = try fetchDouble(id);
    return d > 10.0;
}

fn trace(id: int): string {
    immut _f: bool = fetchFlag(id) recover as err run {
        compare err {
            matches DbError::Missing(table, row):
            return table + "#" + (row.toString()) + ":" + err.message;
            done
            matches DbError::Locked:
            return "locked";
            done
            otherwise:
            return "?";
        }
    };
    return "ok";
}

fn main(): int {
    test::assert(trace(0) == "users#0:no such user", "tag, payload and message survive four levels");
    test::assert(trace(1) == "locked", "a variant with no fields survives too");
    test::assert(trace(2) == "ok", "success passes through untouched");
    io::printline("25/24 PASS");
    return 0;
}

// LEC-004 (audit F-21): `return f();` where `f(): !T` and the enclosing function
// returns exactly `!T` hands the fallible value back as it is -- success or
// error, never unwrapped. It used to be rejected with "function declares '!Rec'
// but returns '!Rec'". Covers a scalar, a struct (boxed on the GC heap), `!void`,
// a generic function, and a method.
import io;
import test;

error ParseError {
    Bad(at: int)
}

struct Rec {
    a: int,
    b: int
}

fn mkrec(a: int, b: int): Rec {
    mut r: Rec = Rec::default();
    r.a = a;
    r.b = b;
    return r;
}

fn parse(n: int): !int {
    if n < 0 { return ParseError::Bad(n); }
    return n * 2;
}

fn parseRec(n: int): !Rec {
    if n < 0 { return ParseError::Bad(n); }
    return mkrec(n, n + 1);
}

fn check(n: int): !void {
    if n < 0 { return ParseError::Bad(n); }
    return;
}

fn<T> wrap(x: T, fail: bool): !T {
    if fail { return ParseError::Bad(0); }
    return x;
}

fn viaParse(n: int): !int { return parse(n); }
fn viaRec(n: int): !Rec { return parseRec(n); }
fn viaCheck(n: int): !void { return check(n); }
fn viaWrap(n: int, fail: bool): !int { return wrap(n, fail); }

// `return` inside a recover block returns from THIS function, so the payload is
// read out here rather than in main.
fn badAt(n: int): int {
    immut v: int = viaParse(n) recover as err run {
        compare err {
            case ParseError::Bad(at):
            return at;
            done
            otherwise:
            return 99;
        }
    };
    return v;
}

fn main(): int {
    immut ok: int = viaParse(4) recover produce -1;
    test::assert(ok == 8, "success passes through");
    test::assert(badAt(0 - 3) == 0 - 3, "the error passes through with its payload");

    immut r: Rec = viaRec(5) recover produce mkrec(0, 0);
    test::assert(r.a == 5 && r.b == 6, "a struct success value passes through (boxed)");
    immut r2: Rec = viaRec(0 - 1) recover produce mkrec(9, 9);
    test::assert(r2.a == 9, "and its error");

    viaCheck(1) recover run {
        test::assert(false, "!void success must not fail");
    };
    viaCheck(0 - 1) recover run {
        io::printline("25/25 void error observed");
    };

    immut w: int = viaWrap(7, false) recover produce -1;
    immut w2: int = viaWrap(7, true) recover produce -1;
    test::assert(w == 7 && w2 == 0 - 1, "a generic !T passes through");
    io::printline("25/25 PASS");
    return 0;
}

// LEC-004: `try` inside a generic function. The operand's success type is the
// type parameter, substituted per instantiation; the error passes through.
import io;
import test;

error GenError {
    Refused(code: int)
}

fn<T> offer(x: T, refuse: bool): !T {
    if refuse { return GenError::Refused(42); }
    return x;
}

fn<T> relay(x: T, refuse: bool): !T {
    immut v: T = try offer(x, refuse);
    return v;
}

fn codeOf(refuse: bool): int {
    immut _s: string = relay("text", refuse) recover as err run {
        switch (err) {
            matches GenError::Refused(code):
            return code;
            done
            otherwise:
            return 0 - 1;
        }
    };
    return 0;
}

fn main(): int {
    immut a: int = relay(5, false) recover produce -1;
    immut b: string = relay("ok", false) recover produce "bad";
    immut c: double = relay(2.5, false) recover produce 0.0;
    test::assert(a == 5, "int instantiation");
    test::assert(b == "ok", "string instantiation");
    test::assert(c == 2.5, "double instantiation");
    test::assert(codeOf(true) == 42, "the payload survives a generic relay");
    test::assert(codeOf(false) == 0, "success");
    io::printline("25/27 PASS");
    return 0;
}

// LEC-004: any sized type is a payload field. Primitives of every width,
// enums, arrays and structs round-trip through construction and a pattern,
// including literal sub-patterns on each comparable type and a guard on a double.
import io;
import test;

enum Level { Low, High }

struct Pair { a: int, b: int }

fn mkpair(a: int, b: int): Pair {
    mut p: Pair = Pair::default();
    p.a = a;
    p.b = b;
    return p;
}

error Wide {
    Prims(i: int, n: int32, d: double, flag: bool, c: char, s: string),
    Mixed(level: Level, p: Pair),
    Arr(values: int[3])
}

fn fail(which: int): not int {
    if which == 0 { return Wide::Prims(1, 2, 3.5, true, 'z', "str"); }
    if which == 1 { return Wide::Mixed(Level::High, mkpair(10, 20)); }
    immut a: int[3] = [7, 8, 9];
    return Wide::Arr(a);
}

fn probe(which: int): int {
    immut _v: int = fail(which) recover as err run {
        compare err {
            matches Wide::Prims(1, n, d, true, 'z', s) if d > 3.0:
            test::assert(n == 2, "int32");
            test::assert(s == "str", "string");
            return 1;
            done
            matches Wide::Mixed(Level::High, Pair { a, b }):
            return a + b;
            done
            matches Wide::Arr(values):
            return values[0] + values[1] + values[2];
            done
            otherwise:
            return 0 - 1;
        }
    };
    return 0;
}

fn main(): int {
    test::assert(probe(0) == 1, "primitives, literals of every kind and a double guard");
    test::assert(probe(1) == 30, "an enum variant literal and a nested struct pattern");
    test::assert(probe(2) == 24, "a fixed array field");
    io::printline("25/28 PASS");
    return 0;
}

// `E::Variant(List::default())`: a default-constructed generic value as a
// payload argument takes its type arguments from the field's declared type.
// It used to reach Codegen as the bare template `List` and die there with an
// internal compiler error ("Cannot allocate unsized type"); the same hole was
// closed for call arguments and `return` in generic_default_from_context.tr
// (tests/38_monomorphization). Found by turf-fuzz probing error payloads.
import list::List;
import map::Map;
import test;

struct Box<T> { v: T, n: int }

error Fail {
    Items(items: List<int>),
    Boxed(b: Box<string>, k: int),
    Table(m: Map<string, int>),
    Plain
}

fn f(k: int): not int {
    if k == 1 { return Fail::Items(List::default()); }
    if k == 2 { return Fail::Boxed(Box::default(), 4, "with a message"); }
    if k == 3 { return Fail::Table(Map::default()); }
    if k == 4 { return Fail::Plain; }
    return k;
}

fn show(k: int): int {
    mut v: int = f(k) recover as err run {
        compare err {
            matches Fail::Items(items):
            mut m: List<int> = items;
            m.push(3);
            return items.length();
            done
            matches Fail::Boxed(b, n):
            test::assert(b.v == "", "a defaulted Box<string> holds an empty string");
            test::assert(err.message == "with a message", "the message follows the fields");
            return b.n + n;
            done
            matches Fail::Table(m):
            return m.length() + 30;
            done
            otherwise:
            return -1;
        }
        return -2;
    };
    return v;
}

fn main(): int {
    test::assert(show(0) == 0, "success");
    test::assert(show(1) == 1, "the payload List is a real, usable List<int>");
    test::assert(show(2) == 4, "Box<string> payload");
    test::assert(show(3) == 30, "Map<string, int> payload");
    test::assert(show(4) == -1, "a variant with no fields");
    return 0;
}

