// random::random_int(min, max) must (a) always stay within [min, max]
// inclusive, and (b) not be stuck returning a constant -- a real bug this
// kind of property test would actually catch (e.g. a seeding mistake that
// makes every call return the same value).
import random;
import test;

fn main(): int {
    const trials: int = 1000;

    // A classic 1..6 die: every single one of 1000 rolls must land in
    // range, and the whole run must not be a single repeated value.
    mut i: int = 0;
    mut first: int = random::random_int(1, 6);
    mut sawDifferent: bool = false;
    while i < trials {
        immut roll: int = random::random_int(1, 6);
        test::assert(roll >= 1 && roll <= 6, "random_int(1, 6) always lands in [1, 6]");
        if roll != first {
            sawDifferent = true;
        }
        i = i + 1;
    }
    test::assert(sawDifferent, "random_int(1, 6) is not stuck returning a single constant value across 1000 calls");

    // A negative-to-positive range, to make sure `min` isn't silently
    // assumed non-negative anywhere in the implementation.
    mut j: int = 0;
    while j < trials {
        immut v: int = random::random_int(-5, 5);
        test::assert(v >= -5 && v <= 5, "random_int(-5, 5) always lands in [-5, 5]");
        j = j + 1;
    }

    // A single-value range (min == max) must always return that value --
    // this also exercises the `% range` path with range == 1.
    mut k: int = 0;
    while k < 20 {
        test::assert(random::random_int(7, 7) == 7, "random_int(7, 7) always returns 7");
        k = k + 1;
    }

    return 0;
}

// `random::random_int` covers any range of ints. One 31-bit draw capped every
// result at min + 2147483647, and `max - min + 1` overflowed (a panic) for a
// range over almost all of `int`.

import test;
import random;

fn main(): int {
    mut big: int = 0;
    mut negatives: int = 0;
    for (int i = 0; i < 2000; i++) {
        immut v: int = random::random_int(0, 10000000000);
        test::assert(v >= 0 && v <= 10000000000, "within [0, 1e10]");
        if v > big {
            big = v;
        }
        immut w: int = random::random_int(-9223372036854775807 - 1, 9223372036854775807);
        if w < 0 {
            negatives += 1;
        }
        immut y: int = random::random_int(9223372036854775800, 9223372036854775807);
        test::assert(y >= 9223372036854775800, "at the top of the range");
        immut z: int = random::random_int(-4611686018427387904, 4611686018427387904);
        test::assert(z >= -4611686018427387904 && z <= 4611686018427387904, "just over 2^62 values");
    }
    test::assert(big > 2147483647, "past 2^31");
    test::assert(negatives > 800 && negatives < 1200, "the whole int range, both halves");
    test::assert(random::random_int(7, 7) == 7, "a range of one");
    return 0;
}

