// Parses a realistic nested JSON document (an object containing a string,
// a number, a bool, a null, a nested array, and a nested object) and
// checks every extracted value.
import io;
import json;
import test;

fn main(): int {
    const text: string = "{\"name\":\"Turf\",\"count\":3,\"active\":true,\"missing\":null,\"tags\":[\"lang\",\"compiler\",\"llvm\"],\"meta\":{\"version\":1,\"stable\":false}}";

    mut v: json::JsonValue = json::parse(text) recover run {
        test::fail("parse should have succeeded on well-formed JSON");
        return 1;
    };

    test::assert_eq(v.get_string("name"), "Turf", "top-level string field");
    test::assert_eq(v.get_number("count"), 3.0, "top-level number field");
    test::assert_eq(v.get_bool("active"), true, "top-level bool field");
    test::assert(v.get("missing").kind == json::JsonType::Null, "top-level null field");

    mut tags: json::JsonValue = v.get("tags");
    test::assert_eq(tags.length(), 3, "nested array length");
    test::assert_eq(tags.at(0).str_val, "lang", "nested array[0]");
    test::assert_eq(tags.at(1).str_val, "compiler", "nested array[1]");
    test::assert_eq(tags.at(2).str_val, "llvm", "nested array[2]");

    mut meta: json::JsonValue = v.get("meta");
    test::assert_eq(meta.get_number("version"), 1.0, "nested object number field");
    test::assert_eq(meta.get_bool("stable"), false, "nested object bool field");

    test::assert(v.has("name"), "has() should find an existing key");
    test::assert(!v.has("nope"), "has() should not find a missing key");

    io::printline("01 PASS: json parse nested");
    return 0;
}

// Builds a JsonValue purely through the constructor/mutator API (no hand-
// written JSON text), stringifies it, re-parses the result, and confirms
// the re-parsed tree is equivalent to the original -- stringify() and
// parse() are each other's inverse for every value shape this module
// supports.
import io;
import json;
import test;

fn main(): int {
    mut obj: json::JsonValue = json::JsonValue::new_object();
    obj.set("name", json::JsonValue::from_string("roundtrip"));
    obj.set("count", json::JsonValue::from_number(42.0));
    obj.set("ok", json::JsonValue::from_bool(true));
    obj.set("nothing", json::JsonValue::null_value());

    mut arr: json::JsonValue = json::JsonValue::new_array();
    arr.push(json::JsonValue::from_number(1.0));
    arr.push(json::JsonValue::from_number(2.0));
    arr.push(json::JsonValue::from_string("three"));
    obj.set("items", arr);

    immut text: string = json::stringify(obj);

    mut reparsed: json::JsonValue = json::parse(text) recover run {
        test::fail("re-parsing a value this module itself stringified should never fail");
        return 1;
    };

    test::assert_eq(reparsed.get_string("name"), "roundtrip", "roundtrip string field");
    test::assert_eq(reparsed.get_number("count"), 42.0, "roundtrip number field");
    test::assert_eq(reparsed.get_bool("ok"), true, "roundtrip bool field");
    test::assert(reparsed.get("nothing").kind == json::JsonType::Null, "roundtrip null field");

    mut items: json::JsonValue = reparsed.get("items");
    test::assert_eq(items.length(), 3, "roundtrip array length");
    test::assert_eq(items.at(0).num_val, 1.0, "roundtrip array[0]");
    test::assert_eq(items.at(1).num_val, 2.0, "roundtrip array[1]");
    test::assert_eq(items.at(2).str_val, "three", "roundtrip array[2]");

    // Also check stringify() on a bare (non-object/array) value works
    // standalone -- a JSON body can legally be a single scalar.
    test::assert_eq(json::stringify(json::JsonValue::from_number(7.0)), "7", "bare number stringify");
    test::assert_eq(json::stringify(json::JsonValue::from_string("hi")), "\"hi\"", "bare string stringify");
    test::assert_eq(json::stringify(json::JsonValue::from_bool(False)), "false", "bare bool stringify");
    test::assert_eq(json::stringify(json::JsonValue::null_value()), "null", "bare null stringify");

    // A string containing characters that need escaping round-trips too.
    mut escaped: json::JsonValue = json::JsonValue::from_string("line1\nline2\t\"quoted\"\\end");
    immut escapedText: string = json::stringify(escaped);
    mut escapedBack: json::JsonValue = json::parse(escapedText) recover run {
        test::fail("re-parsing an escaped string should never fail");
        return 1;
    };
    test::assert_eq(escapedBack.str_val, "line1\nline2\t\"quoted\"\\end", "escaped string roundtrip");

    io::printline("02 PASS: json roundtrip");
    return 0;
}

// LEC-007: json::escape_string is public. Every byte class is checked, including
// the ones the old private version got wrong: control bytes other than
// \n \r \t were emitted raw (invalid JSON), and a byte >= 0x80 must pass through
// (char is a SIGNED byte, so a missing `c >= 0` guard would escape UTF-8 as
// \u00XX garbage).
import json;
import strings;
import test;

fn main(): int {
    test::assert(json::escape_string("plain") == "plain", "plain text is unchanged");
    test::assert(json::escape_string("") == "", "empty");
    test::assert(json::escape_string("a\"b") == "a\\\"b", "quote");
    test::assert(json::escape_string("a\\b") == "a\\\\b", "backslash");
    test::assert(json::escape_string("a\nb\rc\td") == "a\\nb\\rc\\td", "newline, carriage return, tab");
    test::assert(json::escape_string("a/b") == "a/b", "slash is not escaped");

    // Control bytes below 0x20 that have no short form become \u00XX.
    immut ctl: string = strings::repeat("x", 1);
    mut raw: strings::StringBuilder = strings::StringBuilder::default();
    raw.append_char(1 to char);
    raw.append_char(8 to char);
    raw.append_char(12 to char);
    raw.append_char(31 to char);
    test::assert(json::escape_string(raw.to_string()) == "\\u0001\\b\\f\\u001f", "control bytes: \\u00XX and the \\b \\f short forms");
    test::assert(json::escape_string(ctl) == "x", "sanity: an ordinary byte next to the control cases");

    // DEL (127) is not a JSON-required escape.
    mut del: strings::StringBuilder = strings::StringBuilder::default();
    del.append_char(127 to char);
    test::assert(strings::length(json::escape_string(del.to_string())) == 1, "DEL is copied through");

    // UTF-8 (bytes >= 0x80) passes through byte for byte.
    // Built byte by byte (0xC3 0xA9 is "e-acute"): a string literal's handling
    // of non-ASCII source text is not what is under test.
    mut hi: strings::StringBuilder = strings::StringBuilder::default();
    hi.append_char(195 to char;
    hi.append_char(169 to char);
    immut utf: string = hi.to_string();
    immut esc: string = json::escape_string(utf);
    test::assert(strings::length(esc) == 2, "two high bytes stay two bytes");
    test::assert(esc == utf, "non-ASCII bytes are not escaped");

    // stringify uses it, so a string value and an object key are both escaped.
    mut o: json::JsonValue = json::JsonValue::new_object();
    o.set("k\"ey", json::JsonValue::from_string("v\nal"));
    test::assert(json::stringify(o) == "{\"k\\\"ey\":\"v\\nal\"}", "stringify escapes keys and values");

    // Linear: 200,000 quotes -> 400,000 bytes.
    immut big: string = json::escape_string(strings::repeat("\"", 200000));
    test::assert(strings::length(big) == 400000, "large input");
    return 0;
}

// json::parse and json::stringify are linear in the document now (both were
// quadratic: the parser bounds-checked `self.s[self.pos]` and called
// strings::substring() against the whole document per value, and stringify
// grew its result with `result = result + piece`; found by REL-005's
// benchmarks). The rewrite copies string values in segments between escapes,
// so this checks every place a segment starts or ends: escapes at the start,
// the end and back to back, an empty string, bytes above 0x7F, and numbers
// with signs and fractions, then round-trips a 400-object document. Speed is
// bench/json_roundtrip.tr's job: under TURF_GC_STRESS (a collection per
// allocation) a 4000-object round trip took over 700 s. Exponents
// are left out: strings::parse_double() rejects them, so any number with one
// fails the whole parse (the header says only the value is wrong).

use json;
import test;

fn main(): int {
    immut text: string = "[\"\", \"\\\"start\", \"end\\\\\", \"a\\n\\tb\", \"\\/\\r\", \"café\", -12.5, 0]";
    immut v: json::JsonValue = json::parse(text) recover run {
        test::fail("the document is well formed");
        return 1;
    };
    test::assert_eq(v.length(), 8, "eight values");
    test::assert_eq(v.at(0).str_val, "", "empty string");
    test::assert_eq(v.at(1).str_val, "\"start", "escape at the start");
    test::assert_eq(v.at(2).str_val, "end\\", "escape at the end");
    test::assert_eq(v.at(3).str_val, "a\n\tb", "escapes back to back");
    test::assert_eq(v.at(4).str_val, "/\r", "only escapes");
    test::assert_eq(v.at(5).str_val, "café", "bytes above 0x7F pass through");
    test::assert_eq(v.at(6).num_val, -12.5, "negative fraction");
    test::assert_eq(v.at(7).num_val, 0.0, "zero");

    // 400 objects round-tripped, every field read back.
    mut arr: json::JsonValue = json::JsonValue::new_array();
    for i in 0..400 {
        mut o: json::JsonValue = json::JsonValue::new_object();
        o.set("id", json::JsonValue::from_number(i to double));
        o.set("name", json::JsonValue::from_string("item \"" + (i to string) + "\""));
        arr.push(o);
    }
    immut big: string = json::stringify(arr);
    immut back: json::JsonValue = json::parse(big) recover run {
        test::fail("a stringified document parses");
        return 1;
    };
    test::assert_eq(back.length(), 400, "every element came back");
    mut sum: int = 0;
    for i in 0..back.length() {
        immut o: json::JsonValue = back.at(i);
        sum = sum + o.get_int("id");
        if (o.get_string("name") != "item \"" + (i to string) + "\"") {
            test::fail("element " + (i to string) + " has the wrong name");
        }
    }
    test::assert_eq(sum, 79800, "every id came back");
    return 0;
}

