// Regression test: D3 (docs/development/changes/TYPE-002.md, S15) --
// stack.tr's Stack<T>.push() still computed its growth allocation as
// `self.cap * 8` (Type Erasure's "every T is one 8-byte slot" assumption),
// even though monomorphization (TYPE-002) made `data: T*` a REAL T* whose
// GEP scales by sizeof(T). For a 24-byte T this under-allocated the buffer
// by 3x -- confirmed live before this fix: pushing 20 `Big` values aborted
// with glibc's "realloc(): invalid next size" partway through (the buffer
// corrupted the heap's own allocator metadata once growth ran past the
// under-sized allocation). Pre-TYPE-002 this was a safe compile-time ICE
// ("Invalid bitcast"); post-TYPE-002/pre-D3 it was an unsafe RUNTIME abort
// -- a safe compile error traded for memory corruption.
//
// 20 pushes forces multiple growth reallocations (cap: 0 -> 8 -> 16 -> 32),
// and every value is read back and checked, not just "didn't crash" --
// proving the fixed allocation size actually holds real data correctly,
// not merely that it doesn't abort.
import stack::Stack;
import test;

struct Big { a: int, b: int, c: int }
fn Big::new(x: int, y: int, z: int): void { self.a = x; self.b = y; self.c = z; }

fn main(): int {
    mut s: Stack<Big> = Stack::default();
    mut i: int = 0;
    while i < 20 {
        s.push(Big::new(i, i * 2, i * 3));
        i = i + 1;
    }
    test::assert(s.length() == 20, "Stack<Big> should hold 20 elements after growth");

    // Pop all 20 back (LIFO -- last pushed, i = 19, comes first) and verify
    // every field of every element survived the growth reallocations
    // uncorrupted.
    i = 19;
    while i >= 0 {
        mut b: Big = s.pop();
        test::assert(b.a == i, "Big.a corrupted after Stack<Big> growth");
        test::assert(b.b == i * 2, "Big.b corrupted after Stack<Big> growth");
        test::assert(b.c == i * 3, "Big.c corrupted after Stack<Big> growth");
        i = i - 1;
    }
    test::assert(s.length() == 0, "Stack<Big> should be empty after popping everything");

    return 0;
}

// Regression test: D4 (docs/development/changes/TYPE-002.md, S15) -- a
// generic struct containing ANOTHER generic struct at the SAME type
// parameter (`struct Outer<T> { inner: Inner<T> }`) failed to compile:
// `o.put(42)` (Outer<int>) reported "No overload of 'Inner.set' matches
// argument types (int)" inside Outer.put's own instantiation.
//
// Root cause: visitMethodCall()/visitFieldAccess()'s (TypeCheckerCall.cpp)
// shared "recover this struct's own generic substitution by scanning its
// fields" technique never recursed into a field whose OWN declared type is
// itself a GenericType -- so `self.inner`'s type stayed the literal,
// un-substituted `Inner<T>` instead of `Inner<int>`, and `self.inner.set(x)`
// (x: int) had no matching overload against Inner.set's still-generic `T`
// parameter. Both compiled and ran correctly pre-TYPE-002 (erasure never
// needed to substitute anything, since every T was one shared 8-byte slot).
import test;

struct Inner<T> { v: T }
fn<T> Inner.set(x: T): void { self.v = x; }
fn<T> Inner.get(): T { return self.v; }

struct Outer<T> { inner: Inner<T> }
fn<T> Outer.put(x: T): void { self.inner.set(x); }
fn<T> Outer.take(): T { return self.inner.get(); }

fn main(): int {
    mut o: Outer<int> = Outer::default();
    o.put(42);
    test::assert(o.take() == 42, "Outer<int>.take() should round-trip through Inner<int>.set/get");

    auto os = Outer::default();
    os.put("hello");
    test::assert(os.take() == "hello", "Outer<string> must independently coexist with Outer<int>");

    return 0;
}

// Regression test: a generic struct method calling ANOTHER method of the
// SAME struct via `self.` used to silently fail monomorphization discovery
// whenever the CALLEE's own parameter list contained no occurrence of the
// struct's type parameter(s) -- e.g. `fn<T> Box.grow(newCap: int): void`
// called as `self.grow(n)` from another method on `Box<T>`. Found live
// while building STD-003's Map<K,V>/Set<T> hash index (a bucket-table
// growth helper needs a plain `int` capacity argument, unrelated to K/V).
//
// Root cause (src/sema/TypeCheckerCall.cpp, TypeChecker::visitMethodCall): the
// "recover the struct's own generic-parameter substitution" scan (`Subst`)
// re-derived the receiver's type via a fresh `getType(Node.getBase())`
// instead of reusing the ALREADY POINTER-UNWRAPPED `BaseTy` computed a
// little earlier in the same function. `self`'s own declared/registered
// type is always `TurfPointerType(GenericType(StructName, Args))` -- never
// a bare GenericType -- so `dynamic_cast<GenericType*>` on that fresh,
// still-wrapped fetch always failed, and `Subst` came back permanently
// empty for every `self.method(...)` call. This stayed invisible whenever
// the CALLEE's own parameters happened to independently reference the
// struct's type parameter (a SEPARATE substitution source,
// `MethodOwnSubst`, filled the same map entries via matching the callee's
// declared param types against the caller's already-concrete arguments)
// -- it only broke monomorphization discovery entirely (and therefore
// Codegen, with an "Internal error: LLVM function ... not found" a normal
// user could hit with no warning) when NEITHER source had anything to
// contribute, i.e. exactly the shape below.
//
// Fixed by capturing the pointer-unwrapped receiver type into its own
// variable right after the unwrap, and reusing THAT at both places that
// used to re-fetch `getType(Node.getBase())` directly (the `Subst` scan,
// and the Method-kind instantiation-request recording just after it).
import test;

struct Box<T> {
    v: T
}

// Deliberately takes a CONCRETE `int`, not `T` -- the exact shape that used
// to break. `Box.grow` exists purely to be called from `Box.fill` below,
// mirroring map.tr/set.tr's real `bucket_rehash(new_bcap: int)` shape.
fn<T> Box.grow(extra: int): int {
    return extra * 2;
}

fn<T> Box.fill(x: T, extra: int): int {
    self.v = x;
    immutable grown: int = self.grow(extra);
    return grown;
}

fn main(): int {
    mut b: Box<int> = Box{};
    immutable r1: int = b.fill(5, 3);
    test::assert(r1 == 6, "Box<int>.fill -> grow(3) should be 6");
    test::assert(b.v == 5, "Box<int>.fill should still set v");

    // A second, DIFFERENT instantiation (Box<string>) exercising the same
    // self-call shape, to prove the fix isn't accidentally specific to one
    // concrete type argument.
    mut sb: Box<string> = Box::default();
    immutable r2: int = sb.fill("hello", 10);
    test::assert(r2 == 20, "Box<string>.fill -> grow(10) should be 20");
    test::assert(sb.v == "hello", "Box<string>.fill should still set v");

    return 0;
}

// Regression test: SMP-002 (one shared generic-type walker, TypeWalk.h).
// A generic free function taking a GENERIC-STRUCT-typed parameter
// (`fn<T> unwrap(b: Box<T>): T`), called at two DIFFERENT type arguments,
// used to collapse both call sites into ONE bogus monomorphization request
// -- the order-recovery walk this file's own visitFuncCall() uses to build
// a canonical, ORDERED type-argument tuple (TypeCheckerCall.cpp's old
// collectGenericParamNameOrder(), replaced by TypeWalk::collectParamOrder())
// had no `GenericType` case at all, unlike its sibling (the substitution-
// COLLECTING walk, old collectGenericSubstitution(), now TypeWalk::unify())
// which always did. So `unwrap(boxOfInt)` and `unwrap(boxOfDouble)` both
// recovered an EMPTY ordered-type-argument list for their `Box<T>`
// parameter (even though `Subst` itself correctly held `T=int`/`T=double`
// from `unify()`), and both requests collapsed to the identical bogus key
// `unwrap<>` (no type arguments) -- one instantiation cache entry serving
// two call sites that need two DIFFERENT clones.
//
// Confirmed live against the pre-unification code (temporarily removing
// TypeWalk::collectParamOrder()'s GenericType case reproduces it exactly):
// `turf --dump-instantiations` reported a single merged `unwrap<>  (2 call
// sites)` instead of two separate `unwrap<int>`/`unwrap<double>` entries,
// and the merged clone's body failed to compile at all ("Cannot access
// field on non-struct type" on `b.val`, since the wrong/no substitution
// applied to its own `Box<T>` parameter type). See TypeWalk.h's
// collectParamOrder() doc comment for the full mechanism.
import test;

struct Box<T> {
    val: T
}

fn<T> unwrap(b: Box<T>): T {
    return b.val;
}

fn main(): int {
    mut bi: Box<int> = Box.default();
    bi.val = 42;
    mut bd: Box<double> = Box::default();
    bd.val = 3.5;

    mut r: int = unwrap(bi);
    mut d: double = unwrap(bd);

    test::assert(r == 42, "unwrap<int> instantiation gave the wrong value");
    test::assert(d == 3.5, "unwrap<double> instantiation gave the wrong value");
    return 0;
}

// Regression test: SMP-002 (one shared generic-type walker, TypeWalk.h).
// Each of the type shapes TypeWalk::substitute()/unify() must handle,
// exercised as BOTH a generic function's parameter type and its return
// type, so a regression in any one wrapper case (the exact class of bug
// this file's own doc comments elsewhere describe -- `&T` collapsing to
// `T*`, `&?T` doing the same, a callback's own `T` never substituted) is
// caught here directly rather than only by incidental stdlib usage.
//
// `&T` and `&?T` in particular exercise TypeWalk::substitute()'s ordering
// requirement: TurfReferenceType/TurfNullableReferenceType are dynamic_cast
// BEFORE the plain TurfPointerType case (Types.h: both ARE-A
// TurfPointerType) -- checking in the wrong order would silently rebuild a
// substituted `&T`/`&?T` as a plain `T*`.
import test;

// `&T` -- a generic function taking and returning a non-null reference.
fn<T> identityRef(x: &T): &T {
    return x;
}

// `&?T` -- same shape, nullable.
fn<T> identityNullableRef(x: &?T): &?T {
    return x;
}

// `T[]` -- an array of the open parameter, both directions.
fn<T> firstOf(arr: T[]): T {
    return arr[0];
}

// `!T` -- a fallible return type whose success type is the open parameter.
// (SMP-002 gave Resolver::substituteTypeParams a TurfErrorUnionType case it
// never had before, via the shared TypeWalk::substitute() -- previously
// only Monomorphize::substituteConcreteTypes() handled this shape at all.)
fn<T> wrapFallible(x: T): !T {
    return x;
}

fn main(): void {
    mut n: int = 7;
    mut rn: &int = identityRef(&n);
    test::assert(rn == &n, "identityRef<int> should return the same reference");
    test::assert(n == 7, "identityRef<int> must not have mutated its argument");

    mut m: int = 9;
    mut pm: &?int = &m;
    mut rm: &?int = identityNullableRef(pm);
    test::assert(rm == pm, "identityNullableRef<int> should return the same reference");
    test::assert(m == 9, "identityNullableRef<int> must not have mutated its argument");

    mut arr: int[3] = [10, 20, 30];
    test::assert(firstOf(arr) == 10, "firstOf<int> over an int[] array");

    mut s: double = 2.5;
    mut fallibleResult: double = wrapFallible(s) recover produce -1.0;
    test::assert(fallibleResult == 2.5, "wrapFallible<double> should carry the success value through");

    return 0;
}

// Regression test (found by LEC-006): two generic free functions with the same
// name and different parameter lists are two templates. The monomorphizer used
// to key a template by (module, name), so `f(1)` and `f(1, 2)` were ONE
// instantiation whose clone served both calls -- "Incorrect number of
// arguments passed to called function" at codegen. Generic operators hit it at
// once, since every spelling is overloaded (unary/binary `-`, `+` by right
// operand).
import test;

fn<T> f(x: T): int {
    return 1;
}

fn<T> f(x: T, y: T): int {
    return 2;
}

fn<T> g(x: T): int {
    return 10;
}

fn<T> g(T x, int k): int {
    return 20;
}

fn main(): int {
    test::assert(f(1) == 1, "f(x) at int");
    test::assert(f(1, 2) == 2, "f(x, y) at int");
    test::assert(f("a") == 1, "f(x) at string");
    test::assert(f("a", "b") == 2, "f(x, y) at string");

    // Same arity, different parameter types.
    test::assert(g(1) == 10, "g(x) at int");
    test::assert(g(1, 5) == 20, "g(x, k) at int");
