// Regression test (follow-up to LEC-006's 31_overloaded_generic_free_functions):
// the same bug in the METHOD and CONSTRUCTOR drains. Generic templates were
// found by (module, name) alone, so `Box.put(x)` and `Box.put(x, y)` were one
// instantiation whose clone served both calls ("Incorrect number of arguments
// passed to called function" at codegen). A request now names its exact
// declaration for every kind, not just free functions.
import test;

// Methods on a generic struct, overloaded by arity.
struct Box<T> {
    v: T,
    n: int
}

fn<T> Box.new(v: T): void {
    self.v = v;
    self.n = 1;
}

// A second constructor, overloaded by arity.
fn<T> Box.new(v: T, n: int): void {
    self.v = v;
    self.n = n;
}

fn<T> Box.put(x: T): int {
    return 1;
}

fn<T> Box.put(x: T, y: T): int {
    return 2;
}

// Same arity, different parameter types.
fn<T> Box.tag(x: T): int {
    return 10;
}

fn<T> Box.tag(k: int): int {
    return 20;
}

// A NON-generic struct whose methods carry their own type parameters.
struct Plain {
    n: int
}

fn<U> Plain.echo(x: U): int {
    return 100;
}

fn<U> Plain.echo(x: U, y: U): int {
    return 200;
}

fn main(): int {
    mut bi: Box<int> = Box::new(5);
    mut bs: Box<string> = new Box("s", 7);
    test::assert(bi.n == 1, "Box::new(v) at int");
    test::assert(bs.n == 7, "Box::new(v, n) at string");
    test::assert(bs.v == "s", "Box::new(v, n) keeps the value");

    test::assert(bi.put(1) == 1, "put(x) at Box<int>");
    test::assert(bi.put(1, 2) == 2, "put(x, y) at Box<int>");
    test::assert(bs.put("a") == 1, "put(x) at Box<string>");
    test::assert(bs.put("a", "b") == 2, "put(x, y) at Box<string>");

    test::assert(bi.tag(1) == 10, "tag(x: T) at Box<int>");
    test::assert(bs.tag("a") == 10, "tag(x: T) at Box<string>");

    mut p: Plain = Plain::default();
    test::assert(p.echo(1) == 100, "Plain.echo(x) at int");
    test::assert(p.echo(1, 2) == 200, "Plain.echo(x, y) at int");
    test::assert(p.echo("a") == 100, "Plain.echo(x) at string");
    test::assert(p.echo("a", "b") == 200, "Plain.echo(x, y) at string");
    return 0;
}

// A generic constructor takes its type arguments from the type being built,
// and its arguments widen to them like any call's: an int for a double T, an
// untyped literal for an int32 T. The value really is converted.
import list::List;
import test;

struct Box<T> {
    v: T
}

fn<T> Box.new(v: T): void {
    self.v = v;
}

struct Pair<A, B> {
    a: A,
    b: B
}

fn<A, B> Pair.new(a: A, b: B): void {
    self.a = a;
    self.b = b;
}

fn take(b: Box<double>): double {
    return b.v;
}

fn make(): Box<double> {
    return Box::new(3);
}

fn main(): int {
    mut b: Box<double> = Box::new(1);
    test::assert_eq(b.v / 4.0, 0.25, "declared variable");
    b = Box::new(2);
    test::assert_eq(b.v / 4.0, 0.5, "assignment");
    test::assert_eq(take(Box::new(5)) / 2.0, 2.5, "argument");
    test::assert_eq(make().v / 2.0, 1.5, "return value");

    immut n: int = 7;
    mut c: Box<double> = Box::new(n);
    test::assert_eq(c.v / 2.0, 3.5, "an int variable");

    mut small: Box<int32> = Box::new(4);
    test::assert_eq(typeof(small.v), "int32", "an untyped literal for int32");

    immut m: int32 = 3;
    mut wide: Box<int> = Box::new(m);
    test::assert_eq(wide.v + 1, 4, "int32 to int");

    mut p: Pair<string, double> = Pair::new("x", 9);
    test::assert_eq(p.b / 2.0, 4.5, "one of two type arguments widens");

    mut l: List<Box<double>> = List();
    l.push(Box::new(6));
    test::assert_eq(l.get(0).v / 4.0, 1.5, "collection element");

    mut i: Box<int> = Box::new(8);
    test::assert_eq(i.v / 3, 2, "an exact int stays int");
    return 0;
}

// `G::default()` takes its type arguments from where its value goes, not
// only from a declaration or an assignment: a method or function argument,
// a `return`, and the success type of a `!T` return. Its own type is the bare
// template `Box`, so before, `bs.push(Box::default())` died in Codegen with
// "struct method call argument type mismatch" and `return Box::default();`
// with an unsized-type verifier error. Found while testing LEC-009
// (`grid.push(List::default())`).
import list::List;
import test;

struct Box<T> {
    v: T,
    w: int
}

fn make(): Box<int> {
    return Box::default();
}

error E {
    Bad,
}

fn try_make(ok: bool): !Box<int> {
    if (!ok) {
        return E::Bad;

    return Box::default();
}

fn take(b: Box<int>, n: int): int {
    return b.w + n;
}

fn main(): int {
    mut bs: List<Box<int>> = List::default();
    bs.push(Box::default());
    test::assert(bs.length() == 1 && bs[0].w == 0, "push a default");
    test::assert(take(Box::default(), 3) == 3, "default as a call argument");
    test::assert(make().w == 0, "returned default");
    mut b: Box<int> = try_make(true) recover produce make();
    test::assert(b.v == 0, "!T success default");
    mut ls: List<List<int>> = List::default();
    ls.push(List::default());
    ls[0].push(4);
    test::assert(ls[0][0] == 4, "a default inner list is shared");
    return 0;
}

// A generic function used as a value takes its type arguments from the
// function type its position expects: a declared variable, an assignment, a
// return type, a parameter, or a call through a function value. Each
// instantiation is its own clone, the same one a direct call would use.
import test;

fn<T> id(x: T): T {
    return x;
}

fn<T> twice(x: T, f: fn(T): T): T {
    return f(f(x));
}

fn<A, B> second(a: A, b: B): B {
    return b;
}

fn apply(f: fn(int): int, x: int): int {
    return f(x);
}

fn pick(): fn(string): string {
    return id;
}

fn<T> through_value(x: T): T {
    immut f: fn(T): T = id;
    return f(x);
}

fn inc(n: int): int {
    return n + 1;
}

fn main(): int {
    immut fi: fn(int): int = id;
    fs := id;
    test::assert_eq(fi(7), 7, "declared variable, int");
    test::assert_eq(fs("hi"), "hi", "the same function at string");

    mut g: fn(double): double = id;
    g = id;
    test::assert_eq(g(2.5), 2.5, "assignment");

    test::assert_eq(apply(id, 9), 9, "argument to a non-generic parameter");
    immut picked: fn(string): string = pick();
    test::assert_eq(picked("x"), "x", "return value");
    test::assert_eq(twice(3, inc), 5, "a generic callee takes a plain function");
    test::assert_eq(through_value(4), 4, "a value inside a generic body");

    immut h: fn(int, string): string = second;
    test::assert_eq(h(1, "b"), "b", "two type parameters");

    immut call: fn(fn(int): int, int): int = apply;
    test::assert_eq(call(id, 11), 11, "argument through a function value");
    test::assert_eq(id(5), 5, "a direct call still works beside the value");
    return 0;
}

