// Regression test: OVH-006 (docs/planning/OVERHAUL_REMAINING_WORK.md), the
// `mem::Pool<T>.free_all()` shape STD-003 (docs/development/changes/STD-003.md,
// "What this fix does NOT reach") disclosed as unfixable at the time.
//
// STD-003 tried making `mem::Pool<T>`'s free_pool a genuine generic method
// (`fn<T> Pool.free_all(): void { free(self.items[i]); }`, using the
// original file's bare, unqualified `free` -- this test instead qualifies
// every call as `mem::free`/`mem::malloc` since it imports `mem` by name,
// not by path, and picks up no bare aliases) and found it rejected with
// "No overload of 'free' matches argument types (T)" --
// NOT a cast-legality problem (STD-003's own fix), but because
// `self.items`'s type, inside a generic method's template body, resolved
// through GlobalSymbolTable's registered TurfStructType for the struct: a
// SEPARATE, stale copy of the struct's fields that never got the
// NamedType("T") -> TurfGenericParamType("T") substitution
// Resolver::visitStructDecl() applies to the AST node itself. `free(p:
// void*)`'s ordinary argument-compatibility check has the Rule 1 bypass
// for a genuine TurfGenericParamType (typesCompatible(), Types.cpp) --
// but never got the chance to apply it, because the argument type it saw
// was the stale NamedType("T") instead. Deliberately self-contained (a
// user-defined struct, not `mem::Pool<T>` itself) -- see this session's
// own change record for why `mem.tr` isn't touched.
unsafe module;

import test;
import mem;

struct MiniPool<T> {
    items: T*,
    len: int,
    cap: int
}

fn<T> MiniPool.track(item: T): void {
    if self.len == self.cap {
        self.cap = 4;
        self.items = mem::malloc(self.cap * sizeof(T)) to T*;
    }
    self.items[self.len] = item;
    self.len = self.len + 1;
}

// The exact shape STD-003 tried and found rejected: a generic method
// freeing every tracked (pointer-typed) element through the ordinary,
// concrete `free(p: void*)`, with no explicit cast.
fn<T> MiniPool.free_all(): void {
    mut i: int = 0;
    while i < self.len {
        mem::free(self.items[i]);
        i = i + 1;
    }
    if self.items != null {
        mem::free(self.items to void*);
    }
    self.items = null;
    self.len = 0;
    self.cap = 0;
}

fn main(): string {
    mut p: MiniPool<void*> = MiniPool::default();
    mut a: void* = mem::malloc(8);
    mut b: void* = mem::malloc(8);
    p.track(a);
    p.track(b);
    test::assert(p.len == 2, "MiniPool<void*> should be tracking 2 allocations");

    p.free_all();
    test::assert(p.len == 0, "MiniPool<void*>.free_all() should reset len to 0");

    return 0;
}

// Regression test: OVH-006 (docs/planning/OVERHAUL_REMAINING_WORK.md) --
// a user struct named the same as a stdlib generic's own type parameter
// (`T`, `K`, `V`, `U`) used to break EVERY generic in the program, not just
// the colliding one.
//
// Root cause: GlobalSymbolTable's registered TurfStructType for a generic
// struct (e.g. List<T>) is built once at PARSE time, directly from the
// as-parsed fields -- a SEPARATE object from the StructDeclExprAST AST node
// Resolver::visitStructDecl() rewrites in place (NamedType("T") ->
// TurfGenericParamType("T")). Before this fix, nothing propagated that
// rewrite back into GlobalSymbolTable, so the registered struct's fields
// stayed permanently NamedType("T") -- and every consumer that needed to
// tell "T is this struct's own open type parameter" apart from "T is some
// registered type" did so with a name-lookup heuristic ("not registered =>
// must be a generic param"), which broke the instant an unrelated struct
// happened to be declared under that exact name. Confirmed live before this
// fix: `struct T { x: int }` alongside `import list::List;` made
// `l.pop()` on a `List<int>` report its own return type as the user's
// struct `T`, not `int` ("Return type mismatch: function declares 'int'
// but returns 'T'", raised INSIDE list.tr, at the library's own `return
// self.data[i];`).
//
// This test declares a colliding user struct for every single-letter name
// this codebase's generic collections actually use (T, K, V, U) and drives
// every affected collection plus a user-defined generic free function and
// a user-defined generic method through them, in the SAME program.
import list::List;
use map::Map;
import set::Set;
import stack::Stack;
import queue::Queue;
import test;
import strings;

struct T { x: int }
struct K { y: int }
struct V { z: int }
struct U { w: int }

fn<T> identity(v: T): T { return v; }

struct Box<T> { v: T }
fn<T> Box.get(): T { return self.v; }

fn main(): int {
    // Struct T colliding with List<T>/Stack<T>/Queue<T>/Set<T>'s own "T".
    mut l: List<int> = List::default();
    l.push(5);
    l.push(7);
    test::assert(l.pop() == 7, "List<int>.pop() should return 7, not the user struct 'T'");
    test::assert(l.pop() == 5, "List<int>.pop() should return 5 after the first pop");

    mut s: Stack<int> = Stack::default();
    s.push(11);
    test::assert(s.pop() == 11, "Stack<int>.pop() should return 11, not the user struct 'T'");

    mut q: Queue<int> = Queue::default();
    q.enqueue(13);
    test::assert(q.dequeue() == 13, "Queue<int>.dequeue() should return 13, not the user struct 'T'");

    mut st: Set<int> = Set::default();
    st.add(17);
    test::assert(st.contains(17), "Set<int>.contains(17) should still be true");

    // Struct K and V colliding with Map<K, V>'s own type parameters.
    // Key built at runtime (INV-TEST-1, tests/38_monomorphization/README.md):
    // never compare two identical string literals, since the linker may
    // fold them to the same pointer and hide the K==K dispatch this test
    // exists to exercise.
    mut m: Map<string, int> = Map::default();
    m.put("hello", 42);
    immut key: string = strings::trim(" hello "); // content-equal to "hello", separate allocation (INV-TEST-1)
    test::assert(m.get(key) == 42, "Map<string, int>.get() should return 42, not the user struct 'V'");

    // Struct U colliding with a user-defined generic free function's own
    // type parameter.
    test::assert(identity(9) == 9, "identity<int>(9) should return 9, not the user struct 'U'");
    test::assert(identity("hi") == "hi", "identity<string>(\"hi\") should return \"hi\"");

    // A user-defined generic struct + method, same collision shape as the
    // stdlib collections above, to prove this isn't stdlib-specific.
    mut b: Box<int> = Box::default();
    b.v = 100;
    test::assert(b.get() == 100, "Box<int>.get() should return 100, not the user struct 'T'");

    // The colliding structs themselves must still work as ordinary structs.
    mut tv: T = T::default();
    tv.x = 1;
    mut kv: K = K::default();
    kv.y = 2;
    mut vv: V = V::default();
    vv.z = 3;
    mut uv: U = U::default();
    uv.w = 4;
    test::assert(tv.x + kv.y + vv.z + uv.w == 10, "the colliding structs T/K/V/U must still work as ordinary structs");

    return 0;
}

// LANG-002 (docs/archive/ARCHITECTURE_OVERHAUL.md §8): the proof this
// group's whole reason for existing is closed -- a linked list written
// ENTIRELY in safe TurfLang, no `unsafe { }` anywhere. Before &?T existed,
// `struct Node { next: Node* }` required a top-level `unsafe { }` around the
// struct decl, and no plain function could take/return a raw pointer at
// all -- see docs/architecture/pointers_and_references.md §1.5's OLD
// `unsafe`-wrapped version of this exact same list for comparison.
import test;

struct Node {
    val: int,
    next: &?Node
}

fn push(head: &?Node, n: &Node): &?Node {
    n.next = head;
    return n;
}

fn sum(head: &?Node): int {
    mut total: int = 0;
    &?Node current = head;
    while (current != null) {
        total = total + current.val;
        current = current.next;
    }
    return total;
}

fn length(head: &?Node): int {
    mut count: int = 0;
    mut current: &?Node = head;
    while (current != null) {
        count = count + 1;
        current = current.next;
    }
    return count;
}

// "pop": returns the head's own value and the new head (the old head's
// `next`) -- there's no heap allocator in this test, so "pop" here means
// "detach and report", not "free".
fn popVal(head: &?Node): int {
    if (head == null) {
        return -1;
    }
    return head.val;
}

fn main(): int {
    mut a: Node = Node::default();
    mut b: Node = Node::default();
    mut c: Node = Node::default();
    a.val = 1;
    b.val = 2;
    c.val = 3;

    mut head: &?Node = null;
    test::assert(length(head) == 0, "empty list has length 0");
    test::assert(sum(head) == 0, "empty list sums to 0");

    head = push(head, &a);
    head = push(head, &b);
    head = push(head, &c);

    test::assert(length(head) == 3, "list grew to 3 nodes via push");
    test::assert(sum(head) == 6, "sum traverses every pushed node");
    test::assert(popVal(head) == 3, "the most recently pushed node is now the head");

    return 0;
}

// FDN-001 (docs/planning/ROADMAP_v2.0.0.md, DEC-5): the proof this
// milestone's whole reason for existing is closed -- a linked list of
// DYNAMIC size, built entirely from `heap()`-allocated nodes, no fixed set
// of stack locals the way 01_linked_list.tr's `&a`/`&b`/`&c` needed. Before
// `heap()`, the only safe way to obtain a `&Node` was `&localVar`, so a
// data structure whose size isn't known until runtime (here, 1000 nodes
// built in a loop) was unbuildable in safe TurfLang at all.
//
// churn()/gc_collect() proves the SAME direction every tests/41_gc/*.tr
// file already proves (see that folder's own comments): a structure kept
// reachable only through ordinary local variables survives a forced
// collection, with its contents intact -- not "was reclaimed once
// unreachable", which none of those tests attempt at the Turf-source level
// either (an optimizer is free to keep a checked address alive in a
// register, making that direction non-deterministic to assert here; see
// tests/08_e2e_stress/07_heap_bounded_allocation.tr +
// scripts/smoke/gc_rss_smoke.sh for how the reclaim direction is actually
// verified, the same split 41_gc/11's own comment documents).
import test;
import io;

struct Node {
    val: int,
    next: &?Node
}

fn cons(v: int, next: &?Node): &Node {
    mut n: Node = Node::default();
    n.val = v;
    n.next = next;
    return heap(n);
}

fn sum(head: &?Node): int {
    mut total: int = 0;
    mut current: &?Node = head;
    while (current != null) {
        total = total + current.val;
        current = current.next;
    }
    return total;
}

fn length(head: &?Node): int {
    mut count: int = 0;
    mut current: &?Node = head;
    while (current != null) {
        count = count + 1;
        current = current.next;
    }
    return count;
}

// Same "overwrite whatever stack memory a naive implementation might have
// accidentally left a checked address sitting in" idiom as
// tests/41_gc/01_retention_across_collection.tr -- see that file's own
// comment for why this matters, not just filler between the collection and
// the assertions.
fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 3;
        i = i + 1;
    }
    mut total: int = 0;
    i = 0;
    while i < 64 {
        total = total + buf[i];
        i = i + 1;
    }
    test::assert(total == 6048, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn main(): int {
    immut n: int = 1000;
    mut head: &?Node = null;
    mut i: int = 0;
    while i < n {
        head = cons(i, head);
        i = i + 1;
    }

    test::assert(length(head) == n, "1000 heap()-allocated nodes are all reachable");
    test::assert(sum(head) == 499500, "sum(0..999) == 499500 before collection");

    churn(24);
    gc_collect();
    churn(24);

    test::assert(length(head) == n, "the whole list survives a forced collection while retained");
    test::assert(sum(head) == 499500, "every node's value is intact after collection");

    printf("39/05 PASS: heap()-allocated dynamic linked list survives collection");
    return 0;
}

// FDN-001 (docs/planning/ROADMAP_v2.0.0.md, DEC-5): heap()-allocated nodes
// held in a List<&Node> collection, wired into a cycle (every node has an
// outgoing edge, and the edges loop back on themselves) -- the shape a
// tracing collector has to get right that a naive reference-counting
// scheme could not (a cycle with no external reference is unreachable as a
// WHOLE, never freed one node at a time by a refcount hitting zero).
//
// Adjacency is two parallel List<int> arrays of NODE INDICES (`nextIdx`/
// `skipIdx`) rather than each GraphNode holding its own `List<&GraphNode>`
// field -- LEC-006 (this same roadmap, "collection indexing coherence") is
// the tracked, separate gap that shape would exercise instead of this
// milestone's own: `operator[]`/`operator[]=` are declared concretely for
// `List<int>` only (LIMITATIONS.md item 4), so indexing any OTHER `List<T>`
// falls through to `l.data[i]` direct field access, which needs its own
// `unsafe { }` (the collection's backing buffer stays a raw `T*` per
// OVERHAUL_CLOSURE_AUDIT.md's own note) -- confirmed live while drafting
// this test: `List<&GraphNode>`'s own `[i]` reaches a Codegen assertion
// ("Base is not an array or pointer"), the identical failure a bare
// `List<int*>` (no heap() involved at all) also hits, so this is a
// pre-existing, general, already-roadmapped gap, not something FDN-001
// introduced or is scoped to fix. `nodes` below (the List<&GraphNode> that
// actually holds every heap()-allocated node) is read through
// `nodes.data[i]` inside one `unsafe { }` block for exactly this reason;
// `nextIdx`/`skipIdx` are `List<int>`, so they use ordinary `[]` freely.
#include <list>
import test;
import io;

struct GraphNode {
    id: int
}

fn makeNode(id: int): &GraphNode {
    mut n: GraphNode = GraphNode::default();
    n.id = id;
    return heap(n);
}

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 3;
        i = i + 1;
    }
    mut total: int = 0;
    i = 0;
    while i < 64 {
        total = total + buf[i];
        i = i + 1;
    }
    test::assert(total == 6048, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn main(): int {
    immut n: int = 40;
    mut nodes: List<&GraphNode> = List::default();
    mut nextIdx: List<int> = List::default();
    mut skipIdx: List<int> = List::default();

    mut i: int = 0;
    while i < n {
        nodes.push(makeNode(i));
        nextIdx.push((i + 1) % n);
        skipIdx.push((i + 2) % n);
        i = i + 1;
    }

    churn(24);
    gc_collect();
    churn(24);

    // Reads go through the bounds-checked `List.get()`: `List.data` is private
    // to list.tr (LEC-002), and this test is about the GC keeping every
    // `&GraphNode` alive, not about raw-pointer indexing.
    i = 0;
    while i < n {
        mut nd: &GraphNode = nodes.get(i);
        test::assert(nd.id == i, "each node's id survives collection intact");
        mut nextNode: &GraphNode = nodes.get(nextIdx[i]);
        test::assert(nextNode.id == (i + 1) % n, "next-edge neighbor has the expected id");
        mut skipNode: &GraphNode = nodes.get(skipIdx[i]);
        test::assert(skipNode.id == (i + 2) % n, "skip-edge neighbor has the expected id");
        i = i + 1;
    }

    // Walk the whole cycle starting from node 0 -- n hops on the next-edge
    // graph must visit every node exactly once and return to node 0.
    mut visited: int = 0;
    mut cur: int = 0;
    i = 0;
    while i < n {
        visited = visited + 1;
        cur = nextIdx[cur];
        i = i + 1;
    }
    test::assert(visited == n, "walked all n nodes around the next-edge cycle");
    test::assert(cur == 0, "the cycle returns to node 0 after n hops");

    io::printline("39/07 PASS: heap()-allocated cyclic graph survives collection");
    return 0;
}

// A null check on a `&?T` variable holds across a loop that does not assign
// the variable: inside the loop, and after it. NullabilityPass used to start
// its fixed point from "nothing proven" at every block, so a loop header (whose
// back edge had not been processed yet) dropped every fact and never got it
// back: each function below was E081. Found by turf-fuzz probing for
// reference-graph generation.
import test;

struct Node { val: int, next: &?Node }

fn cons(v: int, next: &?Node): &Node {
    mut n: Node = Node{};
    n.val = v;
    n.next = next;
    return heap(n);
}

// Early return, then a loop that never mentions `p`, then a use.
fn after_loop(p: &?Node): int {
    if (p == null) { return -1; }
    mut k: int = 0;
    while k < 3 { k += 1; }
    return p.val + k;
}

// A use inside `while`, `for .. in a..b` and for-each bodies.
fn inside_loops(p: &?Node): int {
    if (p != null) {
        mut k: int = 0;
        while k < 2 { k += 1; p.val += 1; }
        for r in 0..3 { p.val += r; }
        mut a: int[2] = [10, 20];
        for e in a { p.val += e; }
        return p.val;
    }
    return -1;
}

// `continue` and `break` are edges into the same header and exit.
fn with_jumps(p: &?Node): int {
    if (p == null) { return -1; }
    mut k: int = 0;
    while k < 5 {
        k += 1;
        if k == 2 { continue; }
        if k == 4 { break; }
        p.val += 1;
    }
    return p.val;
}

// A walk: the variable IS assigned in the body, and the loop condition
// narrows it again on every iteration; an inner loop keeps that.
fn walk(head: &?Node): int {
    mut total: int = 0;
    mut c: &?Node = head;
    while (c != null) {
        mut j: int = 0;
        while j < 2 { j += 1; total += c.val; }
        c = c.next;
    }
    return total;
}

fn main(): int {
    test::assert(after_loop(null) == -1, "early return on null");
    test::assert(after_loop(cons(4, null)) == 7, "use after a loop");
    test::assert(inside_loops(null) == -1, "not entered on null");
    test::assert(inside_loops(cons(0, null)) == 35, "uses inside three loops");
    test::assert(with_jumps(cons(0, null)) == 2, "continue and break keep the fact");
    test::assert(walk(cons(1, cons(2, cons(3, null)))) == 12, "walk with an inner loop");
    return 0;
}

// What the E081/E082 hints for a non-variable `&?T` tell the user to write,
// and what stays legal on such a value without a check: comparing it with
// null, storing it, passing it to a `&?T` parameter.
import list::List;
use test;

struct Node { val: int, next: &?Node }
struct Holder { head: &?Node }

fn first(p: &?Node): int {
    if (p == null) { return -1; }
    return p.val;
}

fn main(): int {
    mut h: Holder = Holder::default();
    test::assert(h.head == null, "a nullable field compares with null unchecked");
    test::assert(first(h.head) == -1, "and is passed on unchecked");

    mut n: Node = Node::default();
    n.val = 7;
    h.head = heap(n);
    mut r: &?Node = h.head;
    if (r != null) {
        test::assert(r.val == 7, "read through a checked variable");
        r.val = 8;
        mut s: &Node = (r to &Node);
        test::assert(s.val == 8, "cast inside the check");
    }

    mut l: List<&?Node> = List::default();
    l.push(h.head);
    l.push(null);
    mut e: &?Node = l[0];
    mut total: int = 0;
    if (e != null) { total += e.val; }
    e = l[1];
    if (e != null) { total += e.val; }
    test::assert(total == 8, "list elements through a variable");
    return 0;
}

// Narrowing reaches into a `recover run { }` block: a guard inside the block
// narrows within it, and a check before the statement holds inside it. The
// block gets its own CFG for this; without one, checking the block at all
// (fail_deref_inside_recover_block.tr) would reject the guarded form.
import test;

struct Node { val: int }

error Fail { Always }

fn bad(): !int {
    return Fail::Always;
}

fn guarded(p: &?Node): int {
    mut v: int = bad() recover run {
        if (p != null) {
            return p.val;
        }
        return -1;
    };
    return v;
}

fn checked_before(p: &?Node): int {
    if (p == null) {
        return -2;
    }
    mut v: int = bad() recover run { return p.val; };
    return v;
}

fn nested(p: &?Node): int {
    mut v: int = bad() recover run {
        if (p == null) {
            return -3;
        }
        mut w: int = bad() recover run { return p.val; };
        return w;
    };
    return v;
}

// A `continue`/`break` inside the block belongs to a loop outside it. The
// block's own CFG treats it as leaving the block; this used to be E007
// "'continue' used outside of a loop" (turf-fuzz differential seed 424234).
fn in_loop(p: &?Node): int {
    mut t: int = 0;
    for (i in 0..3) {
        mut v: int = bad() recover run {
            if (p == null) {
                continue;
            }
            if (i == 2) {
                break;
            }
            t = t + p.val;
            continue;
        };
        t = t + v;
    }
    return t;
}

fn main(): int {
    mut n: Node = Node::default();
    n.val = 7;
    mut none: &?Node = null;
    test::assert_eq(guarded(&n), 7, "guard inside the block");
    test::assert_eq(guarded(none), -1, "guard inside the block, null");
    test::assert_eq(checked_before(&n), 7, "check before the statement");
    test::assert_eq(checked_before(none), -2, "check before the statement, null");
    test::assert_eq(nested(&n), 7, "nested recover");
    test::assert_eq(nested(none), -3, "nested recover, null");
    test::assert_eq(in_loop(&n), 14, "continue and break inside the block");
    test::assert_eq(in_loop(none), 0, "continue inside the block, null");
    return 0;
}

// A call's result may point into this frame when an argument does: `pick`
// returns one of two locals here, so storing `&c` into it stays inside the
// frame and is not an escape. Only a call none of whose arguments reach the
// frame is long-lived (fail_escape_store_into_call_result.tr).

import test;

struct N { val: int, nxet: &?N }

fn pick(a: &N, b: &N, first: bool): &N {
    if (first) {
        return a;
    }
    return b;
}

fn main(): int {
    mut a: N = N::default();
    mut b: N = N::default();
    mut c: N = N::default();
    c.val = 3;
    mut x: &N = pick(&a, &b, true);
    x.next = &c;
    mut q: &?N = a.next;
    mut got: int = 0;
    if (q != null) {
        got = q.val;
    }
    test::assert(got == 3, "stored through the call result into a local");
    return 0;
}

// The accepted side of fail_escape_return_give_of_locals.tr: a `give` of two
// heap() references, and of two references the caller handed in.
import test;

struct Node { val: int, next: &?Node }

fn pick(c: int, n: Node): &Node {
    return (c > 0 give heap(n) otherwise heap(Node::default()));
}

fn either(c: int, a: &Node, b: &Node): &Node {
    return a if (c > 0 else b);
}

fn main(): int {
    mut n: Node = Node::default();
    n.val = 42;
    test::assert(pick(1, n).val == 42, "give of heap()");
    mut a: &Node = heap(n);
    mut b: &Node = heap(Node::default());
    test::assert(either(0, a, b).val == 0, "give of parameters");
    return 0;
}

// FDN-002 (docs/planning/ROADMAP_v2.0.0.md; docs/development/changes/
// FDN-002.md): positive case -- returning `heap(local)` is Heap provenance,
// never flagged. `heap()` copies `local`'s VALUE onto a fresh GC-heap block
// (FDN-001); the local's own stack storage is irrelevant once the copy
// exists, so this must keep compiling and running exactly as FDN-001 left
// it.
import test;

struct Node {
    val: int
}

fn make(): &Node {
    let local: Node = Node::default();
    local.val = 9;
    return heap(local);
}

fn main(): int {
    mut p: &Node = make();
    test::assert(p.val == 9, "returning heap(local) still works");
    return 0;
}

// FDN-002 (docs/planning/ROADMAP_v2.0.0.md; docs/development/changes/
// FDN-002.md): positive case -- returning `&param.field` through an
// already-reference-typed parameter is Param provenance, not Stack.
// `param` points at whatever the CALLER already owns (here, `main`'s own
// `o`, which outlives this call), so this must keep compiling and running.
import test;

struct Inner {
    val: int
}

struct Outer {
    inner: Inner
}

fn innerAddr(param: &Outer) -> &Inner {
    return &param.inner;
}

fn main(): int {
    mut o: Outer = Outer::default();
    o.inner.val = 7;
    mut p: &Inner = innerAddr(&o);
