// tests/41_gc/01_retention_across_collection.tr
// MEM-002 (docs/archive/ARCHITECTURE_OVERHAUL.md §8/§14) -- the collector's
// most basic completion criterion, stated verbatim in the roadmap's own
// Testing scope: "keep a reference only in a local; force collection; use
// the object afterwards and assert its contents." (U-3, §11.)
//
// `l` is the ONLY thing keeping the List<int>'s backing buffer (and, once
// pushed, each string) reachable -- if the collector's conservative stack
// scan failed to find it as a root, gc_collect() would free the buffer out
// from under `l`, and the assertions below would read freed memory (data
// corruption, not necessarily a crash -- exactly the class of bug
// tests/13_string_stdlib/17_stress_10k_concat.tr caught live during this
// group's own development, see docs/development/changes/MEM-002.md).
//
// churn() between the collection and the assertions overwrites whatever
// stack memory a NAIVE implementation might have accidentally left `l`'s
// address sitting in from an earlier, now-dead call frame -- without it, a
// bug in root-finding could pass by accident (stale garbage on the stack
// happening to still contain the right address), which would be a much
// weaker test than intended.

import list::List;
import test;
import io;

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0; // satisfies definite assignment for the whole array before the loop below
    mut i: double = 0;
    while i < 64 {
        buf[i] = i * 3;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 6048, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn main(): int {
    mut l: List<int> = List::default();
    mut i: int = 0;
    while i < 500 {
        l.push(i * 2);
        i = i + 1;
    }

    churn(24);
    gc_collect();
    churn(24);

    test::assert(l.length() == 500, "retained List<int> keeps its length");
    test::assert(l[0] == 0, "retained List<int> keeps element 0");
    test::assert(l[250] == 500, "retained List<int> keeps a middle element");
    test::assert(l[499] == 998, "retained List<int> keeps the last element");

    io::printline("41/01 PASS: List<int> retained correctly across a forced collection");
    return 0;
}

// tests/41_gc/02_precise_element_tracing.tr
// MEM-002: `List<int>` (tests/41_gc/01_...) only exercises a collection
// whose element type has NO pointer words -- CastExprAST::codegen()'s new
// per-element TurfTypeDesc (CodegenExpr.cpp, consumed by
// getOrCreateElementTurfTypeDesc(), CodegenStruct.cpp) still gets built and
// passed for it, but every bit of its pointer_word_bitmap is 0, so
// gc_scan_block_precise() (turfrt_gc.c) never actually walks INTO one of
// its elements looking for an outgoing pointer.
//
// `List<string>` is the case that matters: each element genuinely IS a
// pointer into a SEPARATE GC-heap allocation (a string buffer). If the
// per-element descriptor's bitmap were wrong (e.g. still 0, as it would be
// under MEM-001's literal-NULL-always behaviour), a string reachable ONLY
// by being stored inside this list's backing buffer -- never through any
// other local of its own -- would be swept out from under the list the
// moment nothing else roots it, corrupting the list's own contents on next
// read. This is the actual "trace one object's contents to find further
// objects" half of a real mark-sweep collector, not just "don't free the
// object I'm holding directly."

import list::List;
import strings;
import test;
import io;

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0; // satisfies definite assignment for the whole array before the loop below
    mut i: int = 0;
    while i < 64 {
        buf[i] = i;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 2016, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

// Builds each string via strings::repeat() so it is a genuinely fresh,
// separately gc_alloc'd buffer -- reachable, after this function returns,
// ONLY through `List<string>`'s own backing buffer (read back via
// `.get(i)`, OVH-003's bounds-checked accessor over the identical `data:
// T*` field this comment used to name directly), never through any
// surviving local of its own (the whole point of this test).
fn build(): List<string> {
    mut l: List<string> = List::default();
    l.push(strings::repeat("a", 40));
    l.push(strings::repeat("b", 40));
    l.push(strings::repeat("c", 40));
    return l;
}

fn main(): int {
    mut l: List<string> = build();

    churn(24);
    gc_collect();
    churn(24);
    gc_collect();

    test::assert(l.size() == 3, "List<string> keeps its length");
    test::assert(strings::length(l.get(0)) == 40, "element 0's string survives with correct length");
    test::assert(strings::starts_with(l.get(0), "a"), "element 0's string content survives");
    test::assert(strings::starts_with(l.get(1), "b"), "element 1's string content survives");
    test::assert(strings::starts_with(l.get(2), "c"), "element 2's string content survives");

    io::printline("41/02 PASS: List<string> elements precisely traced through a forced collection");
    return 0;
}

