// tests/41_gc/09_boxed_fallible_success_survives_collection.tr
// OVH-002 (docs/planning/OVERHAUL_REMAINING_WORK.md): `BoxToI64Slot()`
// (src/codegen/CodegenCore.cpp) heap-boxes a `!T` success value wider than 64 bits
// (a struct, here `Rec`) so it can outlive the function that returns it --
// the box's ADDRESS is stashed in the `FallibleValue`'s `successBits`
// slot, which sits on the stack as an ordinary `!Rec`-typed local
// (`held`), so the box itself is always found correctly by the collector's
// conservative stack scan.
//
// The bug this test reproduces: before this fix, the box was a bare
// `malloc()` block -- never registered with the collector's block table
// at all (`turf_gc_register_block` is only called by `turf_rt_alloc`/
// `turf_rt_alloc_zeroed`/`turf_rt_realloc`), so even though the BOX's own
// address survived conservative scanning, the collector's mark phase had
// no reason to ever walk INTO an unregistered block looking for further
// pointers. `Rec.name` -- a GC-heap `string` living ONLY inside that box
// -- therefore had no root of its own the moment nothing else pointed at
// it, and got swept by the very next collection, corrupting `r.name` when
// finally read back after `recover`. Now the box is `turf_rt_alloc`'d with
// `Rec`'s own real descriptor, so it is both a registered, root-findable
// block AND precisely traced into.
//
// `junk()` between the two collections allocates a few thousand throwaway
// strings (docs/planning/OVERHAUL_REMAINING_WORK.md §1's own guidance) so
// a freed block is actually REUSED with different content, not merely
// freed-but-still-readable-by-luck.

import strings;
import test;
import io;

struct Rec {
    name: string,
    other: int
}

fn makeRec(): !Rec {
    mut r: Rec = Rec();
    r.name = strings::repeat("z", 40);
    r.other = 42;
    return r;
}

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 13;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 26208, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn junk(n: int): void {
    mut i: int = 0;
    while i < n {
        strings::repeat("j", 40);
        i = i + 1;
    }
}

fn main(): int {
    // Hold the fallible value itself (still boxed -- the box is only
    // unboxed by the `recover` below) across a forced collection, exactly
    // per OVH-002's own testing scope: "hold a !Rec in a local across a
    // collection, then recover."
    mut held: !Rec = makeRec();

    churn(24);
    gc_collect();
    junk(2000);
    churn(24);
    gc_collect();

    mut r: Rec = held recover produce Rec::default();

    test::assert(r.other == 42, "boxed struct's plain-int field survives a forced collection");
    test::assert(strings::length(r.name) == 40, "boxed struct's string field survives with correct length -- OVH-002's actual reproducer");
    test::assert(strings::starts_with(r.name, "z"), "boxed struct's string field content survives");

    io::printline("41/09 PASS: a boxed oversized !T success value's own GC-heap contents are precisely traced through a forced collection");
    return 0;
}

// tests/41_gc/09_error_payload_survives_collection.tr
// LEC-004 (FREEZE.md §6.18): an error value is `{ tag, message, payload }`, the
// payload a GC-allocated per-variant struct with its OWN type descriptor
// (`errpayload.<Error>.<Variant>`). A `string`, a `List<string>` and a nested
// struct held ONLY inside a payload must be traced through a forced collection
// that runs inside `recover as err run` -- after `err` is bound, before its
// payload is read -- exactly the window 08 uses for the message. Were the
// payload block untraced (or its descriptor wrong), the strings would be swept
// and later reused by `junk()`'s throwaway allocations, so the contents would no
// longer match. Run at `-O0` as well (AGENTS.md): conservative register scanning
// can otherwise mask a missed root by luck.
import list::List;
import strings;
import test;
import io;

struct Point { x: int, y: int }

fn mkpoint(a: int, b: int): Point {
    Point p = Point::default();
    p.x = a;
    p.y = b;
    return p;
}

error Shape {
    Dot(p: Point),
    Labels(names: List<string>, count: int),
    Named(label: string, at: Point),
    Empty
}

fn mkdot(a: int, b: int): !int {
    return Shape::Dot(mkpoint(a, b));
}

fn mklabels(n: int): !int {
    mut l: List<string> = List::default();
    mut i: int = 0;
    while i < n {
        l.push(strings::repeat("L", 40 + i));
        i = i + 1;
    }
    return Shape::Labels(l, n, "with message");
}

fn mknamed(): !int {
    return Shape::Named(strings::repeat("o", 40), mkpoint(7, 8));
}

fn junk(n: int): void {
    mut i: int = 0;
    while i < n {
        strings::repeat("j", 40);
        i = i + 1;
    }
}

fn readDot(): int {
    immut v: int = mkdot(3, 4) recover as err run {
        junk(2000);
        gc_collect();
        compare err {
            matches Shape::Dot(Point { x, y }):
            test::assert(x == 3, "dot x");
            test::assert(y == 4, "dot y");
            return x + y;
            done
            otherwise:
            return 0 - 1;
        }
    };
    return v;
}

fn readLabels(): int {
    immut v: int = mklabels(5) recover as err run {
        junk(2000);
        gc_collect();
        junk(2000);
        gc_collect();
        compare err {
            matches Shape::Labels(names, count):
            test::assert(count == 5, "count");
            test::assert(names.length() == 5, "len");
            test::assert(strings::length(names.get(4)) == 44, "element 4 length");
            test::assert(strings::starts_with(names.get(2), "L"), "element 2");
            test::assert(err.message == "with message", "msg");
            return count;
            done
            otherwise:
            return 0 - 2;
        }
    };
    return v;
}

fn readNamed(): int {
    immut v: int = mknamed() recover as err run {
        junk(2000);
        gc_collect();
        compare err {
            matches Shape::Named(label, Point { x: 7, y }):
            test::assert(strings::length(label) == 40, "label");
            test::assert(y == 8, "y");
            return y;
            done
            matches Shape::Named(_, _):
            return 0 - 3;
            done
            otherwise:
            return 0 - 4;
        }
    };
    return v;
}

fn main(): int {
    test::assert(readDot() == 7, "dot");
    test::assert(readLabels() == 5, "labels");
    test::assert(readNamed() == 8, "named");
    io::printline("41/09 PASS: a payload's GC-heap string, List<string> and nested struct are traced through a forced collection");
    return 0;
}

// tests/41_gc/10_int_double_to_string_survives_collection.tr
// Adjacent to OVH-002 (docs/planning/OVERHAUL_REMAINING_WORK.md), found
// live while implementing it: `int to string`/`double to string` casts
// (`CastToType()`, src/codegen/CodegenExpr.cpp) built their result buffer with a
// bare `malloc(32)`, never registered with the collector's block table at
// all. This is a different shape than OVH-002's own four named sites (no
// GC pointer was hidden INSIDE the malloc'd block -- the malloc'd block
// WAS the string), but the same underlying violation: FREEZE.md §6.5 says
// "string values produced by any operation" belong on the GC heap, and a
// `malloc`'d one is permanently invisible to `gc_collect()`/`turf_rt_stats()`
// -- a silent, permanent leak rather than a use-after-free, but still a
// real deviation from the documented memory model. Fixed by routing both
// casts through `turf_rt_alloc(32, NULL)` (`desc == NULL` is correct: the
// buffer holds only formatted digits, never an outgoing pointer).
//
// `s`/`d` are held only in `main()`'s own locals across a forced
// collection with real allocation pressure in between -- the basic
// retention property (`tests/41_gc/01_retention_across_collection.tr`'s
// own shape), which a `malloc`'d, unregistered string trivially "passes"
// (nothing ever frees leaked memory) but which this test also uses
// `TURF_RT_STATS_DUMP`-visible accounting (verified manually while
// developing this fix, not asserted here) to confirm is now a REAL,
// tracked GC-heap block, not merely accidentally-still-valid memory.

import strings;
import test;
import io;

fn churn(depth: int): void {
    mut buf: int[64];
    buf[0] = 0;
    mut i: int = 0;
    while i < 64 {
        buf[i] = i * 23;
        i = i + 1;
    }
    mut sum: int = 0;
    i = 0;
    while i < 64 {
        sum = sum + buf[i];
        i = i + 1;
    }
    test::assert(sum == 46368, "churn: stack buffer round-trips correctly");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn junk(n: int): void {
    mut i: int = 0;
    while i < n {
        strings::repeat("j", 6);
        i = i + 1;
    }
}

fn buildInt(): string {
    return (string)424242;
}

fn buildDouble(): string {
    return 3.5 to string;
}

fn main(): int {
    mut s: string = buildInt();
    mut d: string = buildDouble();

    churn(24);
    gc_collect();
    junk(3000);
    churn(24);
    gc_collect();

    test::assert(s == "424242", "an int-to-string result survives a forced collection");
    test::assert(d == "3.5", "a double-to-string result survives a forced collection");

    io::printline("41/10 PASS: int/double-to-string results are real, tracked GC-heap allocations that survive a forced collection");
    return 0;
}

