// tests/41_gc/12_slice_into_heap_struct_survives_collection.tr
// Range slicing (issue #260): `h.data[2..]`, where `h` is a `heap()` block,
// is a `{ ptr, length }` view whose pointer lands in the MIDDLE of that GC
// block -- the array field, two elements in. Once `h` is pointed elsewhere,
// that interior pointer is the block's only reference, so the collector must
// resolve it to its containing block (MEM-002's interior-pointer retention,
// see 03_interior_pointer_retention.tr) or the view would read freed memory.
// Run under TURF_GC_STRESS=1 and at -O0 too (AGENTS.md) -- at -O2 a stale
// copy of `h` in a register can mask a miss.
import test;
import io;

struct Holder {
    data: int[8],
    tag: int
}

fn Holder.new(base: int): void {
    self.data = [base, base + 1, base + 2, base + 3, base + 4, base + 5, base + 6, base + 7];
    self.tag = base;
}

fn make(base: int): &Holder {
    return heap(Holder::new(base));
}

fn churn(depth: int): void {
    // Allocate, so a collection has something to sweep and reuse.
    mut h: &Holder = make(depth * 1000);
    test::assert(h.tag == depth * 1000, "churn: fresh block holds its tag");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn sum(view: int[]): int {
    mut t: int = 0;
    for v in view {
        t += v;
    }
    return t;
}

fn main(): int {
    mut h: &Holder = make(10);
    immut view: int[] = h.data[2..];   // 12..17, interior to h's block
    h = make(500);                     // the first block: only `view` now

    churn(24);
    gc_collect();
    churn(24);
    gc_collect();

    test::assert(view->length() == 6, "the view keeps its length");
    test::assert(view[0] == 12 && view[-1] == 17, "the view's elements survive");
    test::assert(sum(view) == 87, "12+13+14+15+16+17 through a T[] parameter");
    test::assert(h.tag == 500, "the second block is intact too");

    io::printline("41/12 PASS: a slice into a heap() block keeps it alive across collections");
    return 0;
}

// tests/41_gc/14_shared_collection_header_survives_collection.tr
// LEC-009: a collection is a handle to one GC-heap header (allocated by
// `List::default()`), and the header holds the element buffer. Both must stay
// alive when the only path to them is another collection's buffer (a list of
// lists) or a struct field held by value, and the strings in an inner buffer
// must stay alive through it. Each inner list is built in `make_row`, so no
// local of main's holds its handle when collecting. Run under
// TURF_GC_STRESS=1 and at -O0 too.
import list::List;
import map::Map;
import test;
import io;

struct Holder {
    names: Map<string, List<string>>
}

fn churn(depth: int): void {
    mut s: int = (depth * 7) to string;
    test::assert(s.length() > 0, "churn: a fresh string");
    if depth > 0 {
        churn(depth - 1);
    }
}

fn make_row(outer: List<List<string>>, h: Holder, i: int): void {
    mut row: List<string> = List::default();
    row.push((2000 + i) to string);
    outer.push(row);
    h.names.put(i to string, row);
}

fn main(): int {
    mut outer: List<List<string>> = List::default();
    mut h: Holder = Holder::default();
    mut i: int = 0;
    while i < 20 {
        make_row(outer, h, i);
        i++;
    }

    churn(24);
    gc_collect();
    churn(24);
    gc_collect();

    test::assert(outer.length() == 20 && outer[19][0] == "2019", "inner lists survive in a list");
    outer[3].push("x");
    test::assert(h.names.get("3").length() == 2, "the map and the list name the same inner header");
    test::assert(h.names.get("7")[0] == "2007", "inner lists survive in a struct's map");

    io::printline("41/14 PASS: shared collection headers survive collections");
    return 0;
}

// tests/41_gc/15_realloc_across_collections_keeps_blocks.tr
// A realloc (a List or StringBuilder growing) used to cost O(heap): it
// scanned every block allocated since the last collection one by one, and
// shifted the sorted block table to remove the old block. Now a hash index
// finds a pending block, and a sorted-table entry is marked dead and dropped
// at the next collection (found by REL-005's benchmarks). This exercises
// every path that touches: many lists growing in interleaved order before
// any collection (each removal moves another pending block into the gap,
// whose index must follow it), the same lists growing after a collection
// (their buffers are then in the sorted table, so the old entry is marked
// dead), and collections in between, after which every element must still
// read back. Run under TURF_GC_STRESS=1, TURF_GC_VALIDATE=1, at -O0 and with
// the ASan runtime too.
import list::List;
import test;

fn grow(lists: List<List<string>>, round: int): void {
    for i in 0..lists.length() {
        mut l: List<string> = lists[i];
        for k in 0..(i % 7 + 1) {
            l.push((round * 1000 + i * 10 + k) to string);
        }
    }
}

fn check(lists: List<List<string>>, rounds: int): void {
    for i in 0..len(lists) {
        immut l: List<string> = lists[i];
        immut per: int = i % 7 + 1;
        test::assert(l.length() == per * rounds, "every push is still there");
        for r in 0..rounds {
            for k in 0..per {
                immut want: string = (r * 1000 + i * 10 + k) to string;
                if (l[r * per + k] != want) {
                    test::fail("list " + (i to string) + " lost element " + want);
                }
            }
        }
    }
}

fn main(): int {
    mut lists: List<List<string>> = List::default();
    for i in 0..200 {
        lists.push(List::default());
    }
    // Rounds 0-3 before any collection: realloc of pending blocks.
    for round in 0..4 {
        grow(lists, round);
    }
    check(lists, 4);
    gc_collect();
    check(lists, 4);
    // Rounds 4-11 with a collection every other round: realloc of blocks
    // already in the sorted table, and dead entries dropped in between.
    for round in 4..12 {
        grow(lists, round);
        if (round % 2 == 1) {
            gc_collect();
        }
    }
    check(lists, 12);
    mut sb: strings::StringBuilder = strings::StringBuilder::default();
    for i in 0..5000 {
        sb.append(i to string);
        if (i % 1000 == 0) {
            gc_collect();
        }
    }
    immut text: string = sb.to_string();
    test::assert(text.ends_with("4999"), "a builder grown across collections keeps its bytes");
    test::assert(text.starts_with("0123"), "and its start");
    return 0;
}

// `@caller_location` decorates an `operator` too, so an operator that panics
// on a broken precondition can name its caller's line (FREEZE F-API-3; List's
// and Set's `[]` and `[]=` use it). Every operator dispatch path passes the
// hidden argument: binary, unary, compound assignment, index read and index
// write. Each operator records the location it was called from.

import test;
import strings;

struct V { at: string }

@caller_location
operator +(a: V, b: V): V {
    mut r: V = V::default();
    r.at = caller_location;
    return r;
}

@caller_location
operator -(a: V): V {
    let r: V = V::default();
    r.at = caller_location;
    return r;
}

@caller_location
operator [](v: V, i: int): string {
    return caller_location;
}

@caller_location
operator []=(v: &V, i: int, value: int): void {
    v.at = caller_location;
}

fn main(): int {
    mut a: V = V::default();
    mut b: V = V::default();
    test::assert(strings::ends_with((a + b).at, ":39"), "binary operator");
    test::assert(strings::ends_with((-a).at, ":40"), "unary operator");
    a += b;
    test::assert(strings::ends_with(a.at, ":41"), "compound assignment through operator +");
    test::assert(strings::ends_with(b[0], ":43"), "index read");
    b[0] = 1;
    test::assert(strings::ends_with(b.at, ":44"), "index write");
    return 0;
}

// A `@caller_location` function called in method form (UFCS) gets its hidden
// argument too. `s.substring(1, 3)` asserted in codegen (the UFCS branch of
// MethodCallExprAST::codegen() never appended it) while
// `strings::substring(s, 1, 3)` was fine; found writing REL-005's benchmarks.
// A user function behaves the same way, and records the calling line.

import test;
import strings;

@caller_location
fn where(s: string, n: int): string {
    return caller_location;
}

fn main(): int {
    immut s: string = "abcdef";
    test::assert(s->substring(1, 3) == "bc", "substring in method form");
    test::assert(s.substring(1, 3) == strings::substring(s, 1, 3), "both forms agree");
    for i in 0..2 {
        test::assert(s.substring(i, i + 1).length() == 1, "inside a loop");
    }
    immut at: string = s.where(1);
    test::assert(at.ends_with(":22"), "a user function names the calling line");
    return 0;
}

// The compile-time bounds check (E001) uses the same dataflow as check
// elision, and rejected these valid programs: it read `i` as 5 after three
// `i--` statements and after a `defer` that set it to 0, because neither
// write was modelled. A variable written in a way the dataflow does not
// follow now has no constant, so neither access is judged at compile time.
import test;

fn after_postfix(): int {
    mut a: int[3] = [1, 2, 3];
    mut i: int = 5;
    i--;
    i--;
    i--;
    return a[i];
}

fn after_defer(): int {
    mut a: int[3] = [1, 2, 3];
    mut i: int = 5;
    if True {
        defer i = 0;
    }
    return a[i];
}

fn main(): int {
    test::assert(after_postfix() == 3, "a[2] after three i--");
    test::assert(after_defer() == 1, "a[0] after the defer ran");
    return 0;
}

// LEC-003: struct destructuring -- a literal field test, a bound field, `..`,
// and a guard, tried in source order (first match wins).
import test;

struct Point { x: int, y: int }

fn classify(p: Point): int {
    mut r: int;
    compare p {
        matches Point { x: 0, y: 0 }:
        r = 1;
        done
        case Point { x, y } if x == y:
        r = 2;
        done
        matches Point { x: 0, .. }:
        r = 3;
        done
        matches Point { x, y }:
        r = x + y;
        done
    }
    return r;
}

fn main(): int {
    mut a: Point = Point::default();
    test::assert(classify(a) == 1, "origin matches the first arm");
    a.x = 3;
    a.y = 3;
    test::assert(classify(a) == 2, "x == y hits the guarded arm");
    a.x = 0;
    a.y = 7;
    test::assert(classify(a) == 3, "x == 0 with y ignored");
    a.x = 4;
    a.y = 5;
    test::assert(classify(a) == 9, "bindings are the field values");
    return 0;
}

