// LEC-003: a struct pattern nested two levels deep, mixing an enum variant,
// a string literal, `_` and bindings.
import test;

struct Point { x: int, y: int }
enum Color { Red, Green, Blue }
struct Pixel { at: Point, color: Color, label: string }

fn describe(px: Pixel): int {
    mut r: int;
    compare px {
        matches Pixel { at: Point { x: 0, y }, color: Color::Red, .. }:
        r = 100 + y;
        done
        matches Pixel { label: "hi", at: _, .. }:
        r = 200;
        done
        matches _:
        r = -1;
        done
    }
    return r;
}

fn main(): int {
    mut px: Pixel = Pixel();
    px.at.y = 5;
    px.color = Color::Red;
    test::assert(describe(px) == 105, "nested literal + variant + binding");
    px.color = Color::Blue;
    px.label = "hi";
    test::assert(describe(px) == 200, "string literal field");
    px.label = "no";
    test::assert(describe(px) == -1, "falls to the wildcard");
    return 0;
}

// LEC-003: a pattern looks through a safe `&T` reference, and through `self`.
import test;

struct Point { x: int, y: int }

fn viaRef(p: &Point): int {
    mut r: int;
    compare p {
        matches Point { x, y } if x > y:
        r = x;
        done
        matches Point { y, .. }:
        r = y;
        done
    }
    return r;
}

fn Point.larger(): int {
    mut r: int;
    compare self {
        matches Point { x, y } if x >= y:
        r = x;
        done
        matches Point { y, .. }:
        r = y;
        done
    }
    return r;
}

fn main(): int {
    var p: Point = Point::default();
    p.x = 10;
    p.y = 3;
    test::assert(viaRef(&p) == 10, "x > y through a reference");
    p.y = 30;
    test::assert(viaRef(&p) == 30, "else arm through a reference");
    test::assert(p.larger() == 30, "self is destructurable");
    return 0;
}

// LEC-003: a binding shadows an outer name for its arm only, including a
// `for` loop variable.
import test;

struct Point { x: int, y: int }

fn main(): int {
    mut x: int = 100;
    mut p: Point = Point::default();
    p.x = 5;
    p.y = 6;
    switch (p) {
        matches Point { x, y }:
        test::assert(x == 5, "binding x shadows the outer x");
        test::assert(y == 6, "binding y");
        done
    }
    test::assert(x == 100, "the outer x is untouched and visible again");

    mut seen: int = 0;
    for i in 0..3 step i += 1 {
        p.x = i + 10;
        compare p {
            matches Point { x: i, .. }:
            seen = seen + i;
            done
        }
        seen = seen + i;
    }
    test::assert(seen == 10 + 11 + 12 + 0 + 1 + 2, "binding named like the loop variable");
    return 0;
}

