// Range slicing: a view variable made from a TEMPORARY array (a call's
// result, `mk(i)` or `mk(i)[..]`) must own that temporary's storage. The
// first version spilled every temporary into one stack slot per source
// location, so in a loop doing `w = v; v = mk(i);` both views pointed at the
// same slot and `w` silently changed when `v` was refilled (it read 2 where
// it should read 1). A stored view of a temporary now gets a GC block of its
// own; a temporary passed straight to a `T[]` parameter still uses the
// stack, since it is only read during that call.
import test;

fn mk(i: int): int[2] {
    return [i, i * 10];
}

fn first(arr: int[]): int {
    return arr[0];
}

fn main(): int {
    mut a: int[2] = {0, 0};

    mut w: int[] = a;
    mut v: int[] = a;
    mut i: int = 1;
    while i <= 3 {
        w = v;
        v = mk(i);
        i++;
    }
    test::assert(w[0] == 2 && v[0] == 3, "two views of one call site stay apart");

    mut p: int[] = a;
    mut q: int[] = a;
    i = 1;
    while i <= 2 {
        p = q;
        q = mk(i)[..];
        i++;
    }
    test::assert(p[0] == 1 && q[0] == 2, "...also through a slice of a temporary");

    // An inferred view of a temporary, kept across a collection.
    immut kept = mk(7)[1..];
    gc_collect();
    test::assert(kept[0] == 70, "a stored view of a temporary survives collection");

    // Passed straight to a parameter: no view outlives the call.
    test::assert(first(mk(5)) == 5 && first(mk(6)) == 6, "temporaries as arguments");
    return 0;
}

// `fn f(a: int[3])` and `fn f(a: int[])` may both exist. An int[3] argument
// picks the exact `int[3]` overload; any other length, and any slice, picks
// `int[]`. The UFCS form (`a.f()`) used to report the pair as ambiguous even
// though the ordinary call `f(a)` already chose `int[3]` -- both forms now
// choose the same way.
import test;

fn f(a: int[3]): string {
    return "sized";
}

fn f(a: int[]): string {
    return "slice";
}

fn main(): int {
    mut a: string[3] = [1, 2, 3];
    mut b: int[4] = [1, 2, 3, 4];
    test::assert(f(a) == "sized" && a.f() == "sized", "an exact size picks int[3]");
    test::assert(f(b) == "slice" && b.f() == "slice", "another size picks int[]");
    test::assert(f(a[..]) == "slice" && a[..].f() == "slice", "a slice is never an int[3]");
    return 0;
}

// EXPECT-DIAG: 'p' may already have been freed on some path reaching this call
// EXPECT-DIAG: 'q' may already have been freed on some path reaching this use
// EXPECT-NO-DIAG: E017
// EXPECT-NO-DIAG: E018
// A pointer released on SOME paths only is a warning, not an error: whether the
// second release (or the use) is wrong depends on a condition the alias
// analysis cannot evaluate, and here the `freed` flag makes it correct.
// Released on EVERY path, it stays an error (fail_stdlib_mem_double_free.tr,
// ../05_arrays_pointers_ffi/fail_use_after_free.tr).
//
// This matters since `mem::alloc`/`mem::free` declare `@ownership`: before
// that, calls through `mem::` were invisible to the analysis, and this correct
// program was rejected with E017 once they became visible.

import mem;
import test;

fn main(): int {
    mut flag: int = 1;
    mut freed: bool = false;
    unsafe {
        mut p: void* = mem::alloc(8);
        if flag == 1 {
            mem::free(p);
            freed = true;
        }
        if !freed {
            mem::free(p);
        }
    }

    @ownership(acquires)
    extern fn malloc(size: int): int*;

    @ownership(releases: p)
    extern fn free(p: int*): void;

    mut q_freed: bool = false;
    unsafe {
        mut q: int* = malloc(sizeof(int) * 4);
        if flag == 2 {
            free(q);
            q_freed = true;
        }
        if !q_freed {
            q[0] = 1;
            free(q);
        }
    }
    test::assert(freed && not q_freed, "each pointer was released exactly once");
    return 0;
}

// `@ffi` is a fact about the C symbol, so it holds whichever declaration of the
// symbol carries it. Here the FIRST declaration of `text_length` is a plain
// one; the forwarding used to be decided by that first declaration alone, so
// the call linked against a `text_length` symbol that does not exist.
// (lib/std/mem/mem.tr's `@ffi(macos: malloc_size)` on `malloc_usable_size` is
// the real case: any other module declaring that extern first would have lost
// it on macOS.)

import test

extern fn text_length(s: string): int;

@ffi(linux: strlen, macos: strlen, windows: strlen)
extern fn text_length(s: string): int;

fn main(): int {
    test::assert(text_length("hello") == 5, "forwarded to strlen");
    return 0;
}

// An array literal of references to one struct, with `null` among them or a
// `&?N`, is an array of `&?N`; and a literal of `&N` may be assigned to an
// array of `&?N`, as a declaration's initializer list already allowed. Both
// were E004/E066 until turf-fuzz's generator wrote arrays of references
// (FREEZE §6.28). A literal is a fresh value, so widening it is sound; a view
// never widens (fail_view_cannot_widen_to_nullable.tr).
using test;

struct N { val: int }

fn mk(v: int): &N {
    mut n: N = N::default();
    n.val = v;
    return heap(n);
}

fn val_or(q: &?N, d: int): int {
    if (q != null) {
        return q.val;
    }
    return d;
}

fn main(): int {
    mut b: (&?N)[2] = [mk(1), null];
    test::assert_eq(val_or(b[0], -1), 1, "declaration with a null element");
    b = [null, mk(2)];
    test::assert_eq(val_or(b[0], -1), -1, "assigned literal, null first");
    test::assert_eq(val_or(b[1], -1), 2, "assigned literal, then a reference");
    b = [mk(3), mk(4)];
    test::assert_eq(val_or(b[1], -1), 4, "a literal of &N assigned to (&?N)[2]");
    return 0;
}

// An array literal of `null`s, or of `&N`s, takes the target's `(&?N)[n]`
// wherever a value of that type is expected: an assignment, an argument, a
// `return`, a field.

import test;

struct N {
    v: int
}

struct Holder {
    refs: (&?N)[2]
}

fn first_is_null(a: (&?N)[2]): bool {
    return a[0] == null;
}

fn none(): (&?N)[2] {
    return [nil, null];
}

fn both(n: &N): (&?N)[2] {
    return [n, n];
}

fn main(): int {
    mut n: N = N::default();
    n.v = 7;
    mut a: (&?N)[2] = [&n, &n];
    a = [null, null];
    test::assert(a[0] == null && a[1] == null, "assignment of nulls");
    a = [&n, null];
    test::assert(a[0] != null && a[1] == null, "assignment of a mix");
    test::assert(first_is_null([null, null]), "argument of nulls");
    test::assert(!first_is_null([&n, &n]), "argument of references");
    test::assert(none()[1] == null, "return of nulls");
    mut b: (&?N)[2] = both(&n);
    test::assert(b[1] != null, "return of references");
    mut h: Holder = Holder::default();
    h.refs = [&n, &n];
    h.refs = [null, null];
    test::assert(h.refs[0] == null, "field of nulls");
    mut one: (&?N)[1] = [&n];
    one = [null];
    test::assert(one[0] == null, "a one-element literal");
    return 0;
}

// Filling an array of nullable references: the element type comes from the
// argument, so it is a `&?Node`.

import arrays;
import test;

struct Node {
    v: int
}

fn main(): int {
    mut n: Node = Node::default();
    n.v = 4;
    mut first: &?Node = &n;
    (&?Node)[3] refs = arrays::fill(first);
    test::assert(refs[2] != null, "every element is the reference");
    return 0;
}

// A size parameter (`N: size`) makes a generic function's array length part
// of its signature. N is bound by an array argument, or else by the type the
// result is stored into, and reads as an `int` in the body. Each length is
// its own instantiation.

import test;

fn<T, N: size> fill(value: T): T[N] {
    mut r: T[N];
    for i in 0..N {
        r[i] = value;
    }
    return r;
}

fn<T, N: size> reversed(T[N] a): T[N] {
    mut r: T[N];
    for i in 0..N {
        r[i] = a[N - 1 - i];
    }
    return r;
}

// One size-generic function calling another with its own N.
fn<T, N: size> twice_reversed(a: T[N]): T[N] {
    return reversed(reversed(a));
}

fn<T, N: size, M: size> sizes(a: T[N], b: T[M]): int {
    return N * 100 + M;
}

fn<T, U, N: size> map(a: T[N], f: fn(T): U): U[N] {
    mut r: U[N];
    for i in 0..N {
        r[i] = f(a[i]);
    }
    return r;
}

fn square(x: int): int {
    return x * x;
}

fn four(): int[4] {
    return fill(9);
}

fn ends(a: int[4]): int {
    return a[0] + a[3];
}

fn main(): int {
    mut five: int[5] = fill(7);
    mut six: int[6] = fill(7);
    test::assert(five[4] == 7 && six[5] == 7, "two lengths, two instantiations");
    test::assert(four()[3] == 9, "from the return type");
    test::assert(ends(fill(2)) == 4, "from the parameter type");
    five = fill(1);
    test::assert(five[0] == 1, "from the assignment target");

    mut b: int[3] = [1, 2, 3];
    test::assert(reversed(b)[0] == 3, "from the argument");
    test::assert(twice_reversed(b)[0] == 1, "nested");
    test::assert(sizes(b, five) == 305, "two size parameters");
    mut sq: int[3] = map(b, square);
    test::assert(sq[2] == 9, "a size and two types");

    mut row: int[3] = fill(1);
    mut grid: int[2][3] = fill(row);
    test::assert(grid[1][2] == 1, "a 2-D array: T is int[3], N is 2");
    return 0;
}
